    private void TryDeployCurrentSquad(
        Vector3 destination)
    {
        if (!deploymentMode ||
            currentDeploymentSquad == null)
        {
            return;
        }

        SquadController deploying =
            currentDeploymentSquad;

        SquadController attachedLeader =
            deploying.AttachedLeader;

        destination.y = 0f;

        bool legal;

        if (attachedLeader != null &&
            !attachedLeader.IsOnBattlefield)
        {
            legal =
                TryDeployJoinedFormation(
                    deploying,
                    attachedLeader,
                    destination
                );
        }
        else
        {
            Vector3 oldRoot =
                deploying.transform.position;

            deploying.DeployToBattlefield(
                destination
            );

            Physics.SyncTransforms();

            legal =
                DeploymentLocationLegal(
                    deploying,
                    activeFaction
                ) &&
                deploying.IsCoherent() &&
                AllModelsInsideBoard(
                    deploying
                ) &&
                AllModelsHaveLegalPlacement(
                    deploying
                );

            if (!legal)
            {
                bool zoneLegal =
                    DeploymentLocationLegal(
                        deploying,
                        activeFaction
                    );

                bool coherent =
                    deploying.IsCoherent();

                bool insideBoard =
                    AllModelsInsideBoard(
                        deploying
                    );

                bool placementClear =
                    AllModelsHaveLegalPlacement(
                        deploying
                    );

                deploying.StageForDeployment();
                deploying.transform.position =
                    oldRoot;

                if (!zoneLegal)
                {
                    status =
                        "Illegal deployment: the unit is not wholly inside its deployment zone (or does not satisfy Infiltrators).";
                }
                else if (!insideBoard)
                {
                    status =
                        "Illegal deployment: part of the unit is outside the battlefield.";
                }
                else if (!coherent)
                {
                    status =
                        "Illegal deployment: the unit is not in Unit Coherency.";
                }
                else if (!placementClear)
                {
                    status =
                        "Illegal deployment: one or more models overlap a deployed model or blocking terrain.";
                }

                return;
            }
        }

        if (!legal)
            return;

        SquadController placed =
            deploying;

        currentDeploymentSquad = null;

        status =
            placed.DisplayName +
            (placed.AttachedLeader != null
                ? " + " +
                  placed.AttachedLeader.DisplayName +
                  " deployed as one Attached unit."
                : " deployed.");

        AdvanceDeploymentTurn();
    }

    private bool TryDeployJoinedFormation(
        SquadController bodyguard,
        SquadController leader,
        Vector3 requestedCentre)
    {
        if (bodyguard == null ||
            leader == null)
        {
            return false;
        }

        // Deployment happens while both squads are still in the
        // Undeployed state. LivingModelTokens() intentionally returns an
        // empty list for off-battlefield squads, so use the deployment-safe
        // accessor that returns alive model objects regardless of battlefield
        // state.
        List<ModelToken> bodyModels =
            bodyguard.AllLivingModelTokens();

        List<ModelToken> leaderModels =
            leader.AllLivingModelTokens();

        if (bodyModels.Count == 0 ||
            leaderModels.Count == 0)
        {
            status =
                "Attached Unit deployment state error: " +
                bodyguard.DisplayName +
                " has " +
                bodyModels.Count +
                " model(s); " +
                leader.DisplayName +
                " has " +
                leaderModels.Count +
                " model(s).";
            return false;
        }

        Vector3 oldBodyRoot =
            bodyguard.transform.position;

        Vector3 oldLeaderRoot =
            leader.transform.position;

        Dictionary<ModelToken, Vector3>
            oldLocalPositions =
                new Dictionary<
                    ModelToken,
                    Vector3
                >();

        foreach (ModelToken model
            in bodyModels.Concat(
                leaderModels))
        {
            oldLocalPositions[model] =
                model.transform.localPosition;
        }

        bodyguard.DeployToBattlefield(
            requestedCentre
        );

        leader.DeployToBattlefield(
            requestedCentre
        );

        List<ModelToken> joined =
            new List<ModelToken>();

        joined.AddRange(
            bodyModels
        );

        // Put Leader models last so the attached Character naturally appears
        // on the outside/back of the generated bodyguard formation.
        joined.AddRange(
            leaderModels
        );

        float maxDiameter =
            joined.Max(
                model =>
                    Mathf.Max(
                        0.70f,
                        model.BaseRadiusInches *
                            2f
                    )
            );

        float spacing =
            maxDiameter +
            0.10f;

        int columns =
            Mathf.Clamp(
                Mathf.FloorToInt(
                    Mathf.Sqrt(
                        joined.Count
                    )
                ),
                2,
                Mathf.Max(
                    2,
                    joined.Count
                )
            );

        int rows =
            Mathf.CeilToInt(
                joined.Count /
                (float)columns
            );

        List<Vector3> offsets =
            new List<Vector3>();

        for (int i = 0;
             i < joined.Count;
             i++)
        {
            int row =
                i / columns;

            int column =
                i % columns;

            float x =
                (column -
                 (columns - 1) *
                 0.5f) *
                spacing;

            float z =
                (row -
                 (rows - 1) *
                 0.5f) *
                spacing;

            offsets.Add(
                new Vector3(
                    x,
                    0f,
                    z
                )
            );
        }

        // Account for the actual edge of each model's base when clamping the
        // generated formation into the battlefield/deployment zone.
        float minOffsetX =
            float.MaxValue;

        float maxOffsetX =
            float.MinValue;

        float minOffsetZ =
            float.MaxValue;

        float maxOffsetZ =
            float.MinValue;

        for (int i = 0;
             i < joined.Count;
             i++)
        {
            float radius =
                joined[i]
                    .BaseRadiusInches;

            minOffsetX =
                Mathf.Min(
                    minOffsetX,
                    offsets[i].x -
                    radius
                );

            maxOffsetX =
                Mathf.Max(
                    maxOffsetX,
                    offsets[i].x +
                    radius
                );

            minOffsetZ =
                Mathf.Min(
                    minOffsetZ,
                    offsets[i].z -
                    radius
                );

            maxOffsetZ =
                Mathf.Max(
                    maxOffsetZ,
                    offsets[i].z +
                    radius
                );
        }

        // Centre bounds are now battlefield-only. The active Chapter
        // Approved deployment polygon is validated separately for every base,
        // which allows diagonal and quarter deployment maps.
        float minCentreX =
            -BoardWidth * 0.5f -
            minOffsetX;

        float maxCentreX =
            BoardWidth * 0.5f -
            maxOffsetX;

        float minCentreZ =
            -BoardDepth * 0.5f -
            minOffsetZ;

        float maxCentreZ =
            BoardDepth * 0.5f -
            maxOffsetZ;

        if (minCentreX >
                maxCentreX ||
            minCentreZ >
                maxCentreZ)
        {
            RestoreFailedJoinedDeployment(
                bodyguard,
                leader,
                oldBodyRoot,
                oldLeaderRoot,
                oldLocalPositions
            );

            status =
                "Illegal deployment: this Attached unit physically cannot fit inside the current deployment zone. Choose a larger battlefield/deployment preset.";

            return false;
        }

        Vector3 clampedCentre =
            requestedCentre;

        clampedCentre.x =
            Mathf.Clamp(
                clampedCentre.x,
                minCentreX,
                maxCentreX
            );

        clampedCentre.z =
            Mathf.Clamp(
                clampedCentre.z,
                minCentreZ,
                maxCentreZ
            );

        clampedCentre.y = 0f;

        List<Vector3> centres =
            BuildDeploymentCentreCandidates(
                clampedCentre,
                minCentreX,
                maxCentreX,
                minCentreZ,
                maxCentreZ
            );

        string lastJoinedDeploymentFailure =
            "no legal formation candidate";

        foreach (Vector3 centre
            in centres)
        {
            for (int i = 0;
                 i < joined.Count;
                 i++)
            {
                Vector3 position =
                    centre +
                    offsets[i];

                position.y =
                    joined[i]
                        .transform.position.y;

                joined[i]
                    .transform.position =
                    position;
            }

            Physics.SyncTransforms();

            string failureReason;

            if (JoinedDeploymentFormationIsLegal(
                    bodyguard,
                    joined,
                    activeFaction,
                    out failureReason))
            {
                bodyguard.RefreshVisuals();
                leader.RefreshVisuals();

                return true;
            }

            lastJoinedDeploymentFailure =
                failureReason;
        }

        RestoreFailedJoinedDeployment(
            bodyguard,
            leader,
            oldBodyRoot,
            oldLeaderRoot,
            oldLocalPositions
        );

        status =
            "Illegal Attached Unit deployment: " +
            lastJoinedDeploymentFailure +
            ".";

        return false;
    }

    private bool ModelOverlapsBlockingTerrain(
        ModelToken model,
        Vector3 destination)
    {
        if (model == null)
            return false;

        float probeRadius =
            Mathf.Max(
                0.20f,
                model.BaseRadiusInches *
                    0.85f
            );

        Vector3 probe =
            destination +
            Vector3.up * 0.35f;

        Collider[] overlaps =
            Physics.OverlapSphere(
                probe,
                probeRadius
            );

        foreach (Collider col
            in overlaps)
        {
            if (col == null)
                continue;

            TerrainFeature terrain =
                col.GetComponent<
                    TerrainFeature
                >();

            if (terrain == null)
            {
                terrain =
                    col.GetComponentInParent<
                        TerrainFeature
                    >();
            }

            if (terrain != null &&
                terrain.BlocksMovement)
            {
                return true;
            }
        }

        return false;
    }

    private void AttachCurrentLeader()
    {
        List<SquadController> candidates =
            CompatibleDeploymentBodyguards();

        if (currentDeploymentSquad == null ||
            !currentDeploymentSquad.IsLeaderUnit)
        {
            status =
                "The current deployment unit is not a Leader.";
            return;
        }

        if (candidates.Count == 0)
        {
            status =
                "No compatible bodyguard exists in this roster/deployment state.";
            return;
        }

        SquadController leader =
            currentDeploymentSquad;

        SquadController bodyguard =
            CurrentDeploymentBodyguardTarget();

        if (bodyguard == null)
        {
            status =
                "No compatible bodyguard exists in this roster/deployment state.";
            return;
        }

        if (!leader.AttachToBodyguard(
            bodyguard))
        {
            status =
                "Leader attachment failed.";
            return;
        }

        if (bodyguard.IsOnBattlefield)
        {
            // Re-layout the complete Attached Unit around the Bodyguard's
            // current centre rather than trying to squeeze the Leader into a
            // single leftover gap.
            Vector3 joinedCentre =
                bodyguard.CurrentCentre();

            if (!TryDeployJoinedFormation(
                    bodyguard,
                    leader,
                    joinedCentre))
            {
                leader.DetachFromBodyguard();
                leader.StageForDeployment();

                status =
                    "Leader attachment could not be completed: " +
                    status;
                return;
            }

            currentDeploymentSquad = null;

            status =
                leader.DisplayName +
                " attached to deployed " +
                bodyguard.DisplayName +
                " and the complete Attached Unit was re-formed legally.";

            AdvanceDeploymentTurn();
            return;
        }

        leader.StageForDeployment();

        currentDeploymentSquad =
            bodyguard;

        deploymentRosterScroll =
            Vector2.zero;

        status =
            leader.DisplayName +
            " attached to " +
            bodyguard.DisplayName +
            ". Place the joined unit now; the Leader deploys with its bodyguard.";
    }

    private bool TryPlaceLeaderNextToBodyguard(
        SquadController leader,
        SquadController bodyguard)
    {
        if (leader == null ||
            bodyguard == null ||
            !bodyguard.IsOnBattlefield)
        {
            return false;
        }

        List<ModelToken> bodyguardModels =
            bodyguard.IsOnBattlefield
            ? bodyguard.LivingModelTokens()
            : bodyguard.AllLivingModelTokens();

        ModelToken leaderModel =
            (leader.IsOnBattlefield
                ? leader.LivingModelTokens()
                : leader.AllLivingModelTokens())
                .FirstOrDefault();

        if (bodyguardModels.Count == 0 ||
            leaderModel == null)
        {
            return false;
        }

        Vector3 originalLeaderRoot =
            leader.transform.position;

        Vector3 bodyCentre =
            bodyguard.CurrentCentre();

        // Build a much denser set of candidate positions than the old
        // eight-direction ring. Large joined units can sit close to a
        // deployment-zone edge, so a valid Leader position may be at an
        // oblique angle between two Bodyguard models.
        List<Vector3> candidates =
            new List<Vector3>();

        foreach (ModelToken anchor
            in bodyguardModels
                .OrderByDescending(
                    model =>
                        HorizontalDistance(
                            model.transform.position,
                            bodyCentre
                        )
                ))
        {
            float contactDistance =
                MinimumModelSeparation(
                    anchor,
                    leaderModel
                );

            float[] radii =
            {
                contactDistance + 0.04f,
                contactDistance + 0.16f,
                Mathf.Min(
                    1.75f,
                    contactDistance + 0.38f
                )
            };

            Vector3 outward =
                anchor.transform.position -
                bodyCentre;

            outward.y = 0f;

            if (outward.sqrMagnitude <
                0.001f)
            {
                outward =
                    Vector3.forward;
            }

            outward.Normalize();

            for (int angle = 0;
                 angle < 360;
                 angle += 15)
            {
                Vector3 direction =
                    Quaternion.Euler(
                        0f,
                        angle,
                        0f
                    ) *
                    outward;

                foreach (float radius
                    in radii)
                {
                    Vector3 candidate =
                        anchor.transform.position +
                        direction *
                        radius;

                    candidate.y = 0f;

                    candidates.Add(
                        candidate
                    );
                }
            }
        }

        // Also sample a ring around the joined unit centre. This catches a
        // legal gap outside a dense formation even when no single anchor's
        // outward vector points directly at it.
        float bodyExtent = 0f;

        foreach (ModelToken model
            in bodyguardModels)
        {
            bodyExtent =
                Mathf.Max(
                    bodyExtent,
                    HorizontalDistance(
                        bodyCentre,
                        model.transform.position
                    ) +
                    model.BaseRadiusInches
                );
        }

        float leaderRing =
            bodyExtent +
            leaderModel.BaseRadiusInches +
            0.08f;

        for (int angle = 0;
             angle < 360;
             angle += 10)
        {
            float radians =
                angle *
                Mathf.Deg2Rad;

            candidates.Add(
                new Vector3(
                    bodyCentre.x +
                        Mathf.Cos(radians) *
                        leaderRing,
                    0f,
                    bodyCentre.z +
                        Mathf.Sin(radians) *
                        leaderRing
                )
            );
        }

        // Prefer positions close to the bodyguard while remaining in the
        // active player's deployment zone.
        candidates =
            candidates
                .OrderBy(
                    candidate =>
                        bodyguardModels.Min(
                            model =>
                                HorizontalDistance(
                                    candidate,
                                    model.transform.position
                                )
                        )
                )
                .ToList();

        foreach (Vector3 candidate
            in candidates)
        {
            leader.DeployToBattlefield(
                candidate
            );

            Physics.SyncTransforms();

            if (!LeaderDeploymentCandidateIsLegal(
                    leader,
                    bodyguard,
                    leaderModel))
            {
                leader.StageForDeployment();
                continue;
            }

            return true;
        }

        leader.StageForDeployment();
        leader.transform.position =
            originalLeaderRoot;

        return false;
    }

    private void BeginBattle()
    {
        if (!Core11PrepareAircraftAndValidateMuster())
            return;


        deploymentMode = false;
        SetDeploymentWorldLabelsVisible(true);
        currentDeploymentSquad = null;
        reservePlacementSquad = null;
        reserveCycleIndex = -1;

        round = 1;

        NotifyBattleStarted();

        NotifyBattleRoundStarted();
        turnsCompletedThisRound = 0;

        if (!IsXcomMode)
        {
            traditionalFirstTurnPending =
                true;

            OpenTraditionalDicePrompt(
                2
            );

            AppendBattleLog(
                "ROLL-OFF",
                "First turn",
                "Players resolve the first-turn roll-off manually. Warboard only needs to know which player won."
            );

            status =
                "TRADITIONAL FIRST-TURN ROLL-OFF: roll one D6 each, reroll ties yourself, then select the winner.";

            return;
        }

        int p1Roll;
        int p2Roll;

        do
        {
            p1Roll =
                DiceRoller.RollD6(
                    DisplayFactionName(
                        factions[0]
                    ) +
                    " first-turn roll"
                );

            p2Roll =
                DiceRoller.RollD6(
                    DisplayFactionName(
                        factions[1]
                    ) +
                    " first-turn roll"
                );
        }
        while (p1Roll == p2Roll);

        firstTurnFactionIndex =
            p1Roll > p2Roll
            ? 0
            : 1;

        activeFactionIndex =
            firstTurnFactionIndex;

        activeFaction =
            factions[
                activeFactionIndex
            ];

        firstTurnRollSummary =
            DisplayFactionName(
                factions[0]
            ) +
            " " +
            p1Roll +
            " vs " +
            DisplayFactionName(
                factions[1]
            ) +
            " " +
            p2Roll +
            "  -  " +
            ActiveFactionDisplayName() +
            " wins the roll-off and takes first turn.";

        StartFactionBattleRoundRules();

        CaptureObjectiveControlAtPhaseStart();
        ClearPhaseDestructionRecords();

        BeginActiveTurn(
            true
        );
    }

    private void BeginActiveTurn(
        bool firstTurn)
    {
        phase = Phase.Command;
        resurrectionOrbUsedThisTurn = false;

        if (factionRules != null)
        {
            factionRules.StartTurn(
                activeFaction
            );
        }

        CaptureObjectiveControlAtPhaseStart();
        ClearPhaseDestructionRecords();
        stratagemsUsedThisPhase.Clear();

        if (missionSystem != null)
        {
            missionSystem.BeginTurn(
                activeFaction,
                round
            );
        }

        foreach (SquadController squad
            in squads)
        {
            if (squad.IsAlive &&
                squad.FactionId ==
                    activeFaction)
            {
                squad.StartTurn();
            }
        }
        GameEventBus.Raise(
            new GameEventContext
            {
                Type =
                    GameEventType.TurnStarted,
                Game = this,
                ActingFaction =
                    activeFaction,
                Phase = phase,
                Note =
                    firstTurn
                    ? "First turn"
                    : "New turn"
            }
        );

        // 11e sequence: Start of Command phase first, then Core CP, then
        // Battle-shock, then Command Abilities.
        RaisePhaseStarted();

        foreach (string faction
            in factions)
        {
            GainCommandPoints(
                faction,
                1
            );
        }

        string battleShockSummary =
            ResolveCommandPhaseBattleShock();

        RefreshObjectiveDisplays();

        status =
            (firstTurn &&
             !string.IsNullOrWhiteSpace(
                firstTurnRollSummary)
                ? firstTurnRollSummary +
                  " | "
                : "") +
            ActiveFactionDisplayName() +
            " Command phase. BOTH players gain +1 CP. " +
            CommandPointText() +
            (string.IsNullOrWhiteSpace(
                battleShockSummary)
                ? " | No Battle-shock tests required."
                : " | " +
                  battleShockSummary);
    }

    private int EffectiveLeadership(
        SquadController unit)
    {
        if (unit == null)
            return 7;

        int leadership =
            unit.BestLeadership();

        if (unit.HasKeyword(
                "wraith construct") &&
            FriendlyKeywordWithin(
                unit,
                "aeldari",
                "psyker",
                12f))
        {
            leadership =
                Mathf.Min(
                    leadership,
                    6
                );
        }

        return leadership;
    }

    private string ResolveCommandPhaseBattleShock()
    {
        List<string> results =
            new List<string>();

        if (!IsXcomMode)
        {
            traditionalBattleShockQueue.Clear();
            traditionalBattleShockUnit = null;
            traditionalBattleShockPending = false;
            traditionalBattleShockLabel =
                "Command phase Battle-shock";

            foreach (SquadController squad
                in squads)
            {
                if (squad == null ||
                    !squad.IsAlive ||
                    !squad.IsOnBattlefield ||
                    squad.IsAttachedLeader ||
                    squad.FactionId !=
                        activeFaction)
                {
                    continue;
                }

                SquadController unit =
                    squad.JoinedActionController();

                bool mustTest =
                    unit.IsBattleShocked ||
                    unit.IsAtOrBelowHalfStrength();

                if (!mustTest)
                    continue;

                traditionalBattleShockQueue.Enqueue(
                    unit
                );
            }

            if (traditionalBattleShockQueue.Count > 0)
            {
                BeginNextTraditionalBattleShock();

                return
                    "Traditional: " +
                    (traditionalBattleShockQueue.Count +
                     (traditionalBattleShockPending
                        ? 1
                        : 0)) +
                    " Battle-shock test(s) require manual tabletop resolution.";
            }

            return "";
        }

        foreach (SquadController squad
            in squads)
        {
            if (squad == null ||
                !squad.IsAlive ||
                !squad.IsOnBattlefield ||
                squad.IsAttachedLeader ||
                squad.FactionId !=
                    activeFaction)
            {
                continue;
            }

            SquadController unit =
                squad.JoinedActionController();

            bool mustTest =
                unit.IsBattleShocked ||
                unit.IsAtOrBelowHalfStrength();

            if (!mustTest)
                continue;

            int leadership =
                EffectiveLeadership(
                    unit
                );

                        // WARBOARD_V46_COMMAND_BATTLESHOCK_DICE
            int battleShockDice =
                WarboardFactionExtensionHub
                    .BattleShockDice(
                        this,
                        unit
                    );

            int roll =
                battleShockDice >= 3
                ? DiceRoller.RollDice(
                    battleShockDice,
                    6,
                    "Battle-shock: " +
                    unit.DisplayName
                  ).Total
                : DiceRoller.Roll2D6(
                    "Battle-shock: " +
                    unit.DisplayName
                  );

            bool passed =
                roll >= leadership;

            unit.SetBattleShocked(
                !passed,
                roll
            );

            AppendBattleLog(
                "BATTLE-SHOCK",
                unit.DisplayName,
                "Leadership " +
                leadership +
                "+  |  roll " +
                roll +
                "  ->  " +
                (passed
                    ? "PASS"
                    : "FAIL  -  BATTLE-SHOCKED (OC 0)")
            );

            results.Add(
                unit.DisplayName +
                " " +
                roll +
                " vs Ld " +
                leadership +
                (passed
                    ? "+ PASS"
                    : "+ FAIL  ->  BATTLE-SHOCKED")
            );
        }

        return string.Join(
            " | ",
            results.ToArray()
        );
    }

        private void RaisePhaseStarted()
    {
        V48ResetPhaseWindows();

        GameEventBus.Raise(
            new GameEventContext
            {
                Type =
                    GameEventType.PhaseStarted,
                Game = this,
                ActingFaction =
                    activeFaction,
                Phase = phase
            }
        );
    }

    private void HandleClick(Vector3 mousePosition)
    {
        Ray ray =
            gameCamera.ScreenPointToRay(mousePosition);

        RaycastHit hit;

        if (!Physics.Raycast(ray, out hit, 1000f))
            return;

        ModelToken clickedModel =
            hit.collider
                .GetComponentInParent<
                    ModelToken
                >();

        SquadController clickedSquad =
            clickedModel != null
            ? clickedModel.Squad
            : hit.collider
                .GetComponentInParent<
                    SquadController
                >();

        ObjectiveController clickedObjective =
            hit.collider
                .GetComponentInParent<
                    ObjectiveController
                >();

        TerrainFeature clickedTerrain =
            hit.collider
                .GetComponentInParent<
                    TerrainFeature
                >();

        // WARBOARD_V49_OBJECTIVE_TERRAIN_CLICK_LINK
        if (clickedObjective == null &&
            clickedTerrain != null)
        {
            ObjectiveTerrainLink49 objectiveLink =
                clickedTerrain.GetComponent<
                    ObjectiveTerrainLink49
                >();

            if (objectiveLink != null)
                clickedObjective = objectiveLink.Objective;
        }

        if (!IsXcomMode &&
            (manualWoundEditMode ||
             manualRestoreEditMode) &&
            clickedModel != null)
        {
            SelectModelForAction(
                clickedModel.Squad
                    .JoinedActionController(),
                clickedModel
            );

            manualRestoreDeadIndex = 0;

            status =
                manualRestoreEditMode
                ? "MANUAL RESTORE: " +
                  clickedModel.Squad
                      .JoinedActionController()
                      .DisplayName +
                  " selected. Use RESTORE controls to return destroyed models."
                : "MANUAL WOUNDS: " +
                  clickedModel.RoleName +
                  " has " +
                  clickedModel.CurrentWounds +
                  "/" +
                  clickedModel.MaxWounds +
                  " wounds. Use the wound controls above the board.";

            return;
        }

        if (interactiveAttack != null &&
            interactiveAttack
                .HasPendingCasualtyChoices)
        {
            if (clickedModel != null)
            {
                TryChooseAttackCasualty(
                    clickedModel
                );
            }
            else
            {
                status =
                    "CASUALTY SELECTION: click a valid model in the damaged unit, or use KEEP AUTOMATIC in the casualty window.";
            }

            return;
        }

        if (missionActionTargetingDefinition !=
                null &&
            missionActionTargetingUnit != null)
        {
            SquadController enemyTarget =
                clickedSquad != null
                ? clickedSquad
                    .JoinedActionController()
                : null;

            string actionResult =
                "Mission action system is unavailable.";

            bool started = false;

            if (missionSystem != null)
            {
                started =
                    missionSystem.StartMissionAction(
                        missionActionTargetingUnit,
                        clickedObjective,
                        clickedTerrain,
                        enemyTarget,
                        out actionResult
                    );
            }

            status = actionResult;

            if (started)
            {
                missionActionTargetingUnit = null;
                missionActionTargetingDefinition =
                    null;

                RefreshMoveRing();
            }

            return;
        }

        if (specialMoveSquad != null)
        {
            if (hit.collider.GetComponent<BoardSurface>() != null)
            {
                TryCompleteSpecialMove(
                    hit.point
                );
            }

            return;
        }

        if (specialShootUnit != null)
        {
            if (clickedSquad != null)
            {
                SquadController target =
                    clickedSquad.JoinedActionController();

                if (target.FactionId !=
                    specialShootUnit.FactionId)
                {
                    TryCompleteSpecialShoot(
                        target
                    );
                }
            }

            return;
        }

        if (deploymentMode)
        {
            if (hit.collider.GetComponent<BoardSurface>() != null)
                TryDeployCurrentSquad(hit.point);

            return;
        }

        if (hit.collider.GetComponent<BoardSurface>() != null &&

            Core11HandleBoardPlacementClick(hit.point))

        {

            return;

        }


        if (reservePlacementSquad != null &&
            phase == Phase.Move)
        {
            if (hit.collider.GetComponent<BoardSurface>() != null)
                TryPlaceReserveSquad(hit.point);

            return;
        }

        if (clickedSquad != null)
        {
            SquadController actionSquad =
                clickedSquad.JoinedActionController();

            string selectableFaction =
                phase == Phase.Fight &&
                fightSequenceActive
                ? fightSelectionFaction
                : activeFaction;

            if (actionSquad.FactionId == selectableFaction)
            {
                ModelToken actionModel =
                    clickedModel;

                HandleFriendlyClick(
                    actionSquad,
                    actionModel
                );

                return;
            }

            if (selectedSquad == null)
                return;

            if (phase == Phase.Shoot)
                TryShoot(
                    selectedSquad,
                    actionSquad
                );
            else if (phase == Phase.Charge)
                TryCharge(
                    selectedSquad,
                    actionSquad
                );
            else if (phase == Phase.Fight)
                TryFight(
                    selectedSquad,
                    actionSquad
                );

            return;
        }

        if (phase == Phase.Move &&
            selectedSquad != null &&
            hit.collider.GetComponent<BoardSurface>() != null)
        {
            if (wholeSquadMoveMode)
                TryMoveWholeSquad(hit.point);
            else if (selectedModel != null)
                TryMoveSelectedModel(hit.point);

            return;
        }

        if (phase == Phase.Fight &&
            fightActivationUnit != null &&
            selectedModel != null &&
            (fightActivationStage ==
                FightActivationStage.PileIn ||
             fightActivationStage ==
                FightActivationStage.Consolidate) &&
            hit.collider.GetComponent<BoardSurface>() != null)
        {
            TryFightStageMoveSelectedModel(
                hit.point
            );

            return;
        }
    }

    private void HandleFriendlyClick(
        SquadController squad,
        ModelToken model)
    {
        if (phase == Phase.Move &&
            squad != null)
        {
            NotifyUnitSelectedToMove(
                squad);
        }

        bool isDoubleClick =
            phase == Phase.Move &&
            model != null &&
            lastFriendlyClickedSquad == squad &&
            Time.time - lastFriendlyClickTime <= DoubleClickWindow;

        lastFriendlyClickTime = Time.time;
        lastFriendlyClickedSquad = squad;

        if (isDoubleClick)
        {
            SelectWholeSquadForMovement(squad);
            return;
        }

        if (phase == Phase.Move &&
            model != null)
        {
            SelectSingleModel(
                squad,
                model
            );
        }
        else if ((phase == Phase.Shoot ||
                  phase == Phase.Charge ||
                  phase == Phase.Fight) &&
                 model != null)
        {
            if (phase == Phase.Fight &&
                fightActivationStage !=
                    FightActivationStage.None &&
                fightActivationUnit != null &&
                squad.JoinedActionController() !=
                    fightActivationUnit)
            {
                status =
                    "Finish the current fight activation before selecting another unit.";
                return;
            }

            SelectModelForAction(
                squad,
                model
            );

            if (phase == Phase.Fight &&
                fightActivationStage ==
                    FightActivationStage.Attacks)
            {
                PrepareFightModelWeaponSelection(
                    model
                );
            }
        }
        else
        {
            SelectSquadForAction(
                squad
            );
        }
    }

    private void SelectModelForAction(
        SquadController squad,
        ModelToken model)
    {
        ClearSelectionVisualOnly();

        selectedSquad = squad;
        selectedModel = model;
        wholeSquadMoveMode = false;

        selectedSquad.SetSelected(true);

        if (selectedSquad.AttachedLeader != null)
        {
            selectedSquad.AttachedLeader
                .SetSelected(true);
        }

        if (model != null &&
            model.Squad != null)
        {
            if (model.Squad ==
                selectedSquad)
            {
                selectedSquad.FocusModel(
                    model
                );
            }
            else
            {
                selectedSquad.FocusModel(
                    null
                );

                model.Squad.FocusModel(
                    model
                );
            }
        }

        UpdateSelectionStatus();
        RefreshMoveRing();
    }

    private void SelectSingleModel(
        SquadController squad,
        ModelToken model)
    {
        ClearSelectionVisualOnly();

        selectedSquad = squad;
        selectedModel = model;
        wholeSquadMoveMode = false;

        selectedSquad.SetSelected(true);

        if (selectedSquad.AttachedLeader != null)
            selectedSquad.AttachedLeader.SetSelected(true);

        if (model.Squad == selectedSquad)
        {
            selectedSquad.FocusModel(model);
        }
        else
        {
            selectedSquad.FocusModel(null);
            model.Squad.FocusModel(model);
        }

        UpdateSelectionStatus();
        RefreshMoveRing();
    }

    private void SelectSquadForAction(
        SquadController squad)
    {
        ClearSelectionVisualOnly();

        selectedSquad = squad;
        selectedModel = null;
        wholeSquadMoveMode = false;

        selectedSquad.SetSelected(true);

        if (selectedSquad.AttachedLeader != null)
            selectedSquad.AttachedLeader.SetSelected(true);

        UpdateSelectionStatus();
        RefreshMoveRing();
    }

    private void UpdateSelectionStatus()
    {
        if (selectedSquad == null)
        {
            status = "No squad selected.";
            return;
        }

        string coherence =
            selectedSquad.IsCoherent()
            ? "COHERENT"
            : "OUT OF COHERENCY";

        status =
            selectedSquad.DisplayName +
            (selectedSquad.HasFallenBack
                ? " | FALL BACK"
                : "") +
            (selectedSquad.HasAdvanced
                ? " | ADVANCED +" +
                  selectedSquad.AdvanceBonus
                : "") +
            " | " +
            selectedSquad.LivingModels +
            "/" +
            selectedSquad.StartingModels +
            " models | " +
            coherence +
            " | " +
            (selectedSquad.AttachedLeader != null
                ? "ATTACHED UNIT  -  " +
                  selectedSquad.LeaderSummary()
                : selectedSquad.LeaderSummary()) +
            " | Loadouts: " +
            selectedSquad.LoadoutSummary();

        if (missionSystem != null &&
            missionSystem.UnitHasStartedAction(
                selectedSquad))
        {
            string actionName =
                missionSystem.ActiveActionName(
                    selectedSquad
                );

            status +=
                " | MISSION ACTION: " +
                (string.IsNullOrWhiteSpace(
                    actionName)
                    ? "started/completed"
                    : actionName);
        }

        if (selectedModel != null &&
            phase == Phase.Move)
        {
            float remaining =
                SelectedModelRemainingMove();

            status +=
                " | selected model remaining move " +
                remaining.ToString("0.0") +
                "  -  blue ring";
        }
        else if (selectedModel != null &&
                 phase == Phase.Shoot)
        {
            float range =
                SelectedModelMaximumRangedRange();

            status +=
                range > 0.01f
                ? " | selected model max usable weapon range " +
                  range.ToString("0.#") +
                  "  -  amber ring"
                : " | selected model has no currently usable ranged weapon";
        }
        else if (selectedModel != null &&
                 phase == Phase.Charge)
        {
            status +=
                SelectedUnitCanCharge()
                ? " | maximum pre-roll charge reach 12  -  red ring"
                : " | this unit cannot currently declare a charge";
        }
        else if (selectedModel != null &&
                 phase == Phase.Fight &&
                 fightActivationUnit != null &&
                 ModelBelongsToFightActivation(
                     selectedModel))
        {
            if (fightActivationStage ==
                    FightActivationStage.PileIn ||
                fightActivationStage ==
                    FightActivationStage.Consolidate)
            {
                Vector3 start;

                if (!fightStageStartPositions
                    .TryGetValue(
                        selectedModel,
                        out start))
                {
                    start =
                        selectedModel
                            .transform.position;
                }

                float used =
                    HorizontalDistance(
                        start,
                        selectedModel
                            .transform.position
                    );

                status +=
                    " | " +
                    (fightActivationStage ==
                        FightActivationStage.PileIn
                        ? "pile-in"
                        : "consolidation") +
                    " " +
                    used.ToString("0.0") +
                    "/" +
                    FightStageMoveLimit()
                        .ToString("0.0") +
                    "″  |  hold ALT to measure";
            }
            else if (fightActivationStage ==
                     FightActivationStage.Attacks)
            {
                status +=
                    fightModelsResolvedThisActivation
                        .Contains(
                            selectedModel)
                    ? " | this model has already resolved its melee attacks"
                    : " | click an enemy target to choose this model's melee weapon";
            }
        }
    }

    private void ClearSelectionVisualOnly()
    {
        if (selectedSquad != null)
        {
            selectedSquad.SetSelected(false);

            if (selectedSquad.AttachedLeader != null)
                selectedSquad.AttachedLeader.SetSelected(false);
        }

        if (moveRing != null)
            moveRing.enabled = false;

        HideMovementCursorMeasure();
    }

    private void ClearSelection()
    {
        ClearSelectionVisualOnly();

        selectedSquad = null;
        selectedModel = null;
        wholeSquadMoveMode = false;

        if (reservePlacementSquad != null)
        {
            reservePlacementSquad = null;
            reserveCycleIndex = -1;
            status = "Reserve placement cancelled.";
        }
        else
        {
            status = "No squad selected.";
        }
    }

    private Dictionary<ModelToken, Vector3>
        CaptureAttachedLeaderPositions(
            SquadController bodyguard)
    {
        if (bodyguard == null ||
            bodyguard.AttachedLeader == null)
        {
            return null;
        }

        return bodyguard.AttachedLeader
            .CaptureLivingPositions();
    }

    private void RestoreAttachedLeaderPositions(
        SquadController bodyguard,
        Dictionary<ModelToken, Vector3> positions)
    {
        if (bodyguard == null ||
            bodyguard.AttachedLeader == null ||
            positions == null)
        {
            return;
        }

        bodyguard.AttachedLeader
            .RestorePositions(positions);

        Physics.SyncTransforms();
    }

    private List<ModelToken> JoinedModels(
        SquadController squad)
    {
        if (squad == null)
            return new List<ModelToken>();

        SquadController actionUnit =
            squad.JoinedActionController();

        return actionUnit
            .JoinedLivingModelTokens();
    }

    private Dictionary<ModelToken, Vector3>
        CaptureJoinedPositions(
            SquadController squad)
    {
        Dictionary<ModelToken, Vector3> result =
            new Dictionary<ModelToken, Vector3>();

        foreach (ModelToken model
            in JoinedModels(squad))
        {
            result[model] =
                model.transform.position;
        }

        return result;
    }

    private void RestoreJoinedPositions(
        Dictionary<ModelToken, Vector3> positions)
    {
        if (positions == null)
            return;

        foreach (
            KeyValuePair<ModelToken, Vector3> pair
            in positions)
        {
            if (pair.Key != null &&
                pair.Key.IsAlive)
            {
                pair.Key.transform.position =
                    pair.Value;
            }
        }

        Physics.SyncTransforms();
    }

    private void HandleBodyguardDestroyed(
        SquadController bodyguard)
    {
        if (bodyguard == null ||
            bodyguard.IsAlive ||
            bodyguard.AttachedLeader == null)
        {
            return;
        }

        SquadController leader =
            bodyguard.DetachAttachedLeader();

        if (leader != null)
        {
            leader.HasMoved =
                bodyguard.HasMoved;

            leader.HasShot =
                bodyguard.HasShot;

            leader.HasCharged =
                bodyguard.HasCharged;

            leader.HasFought =
                bodyguard.HasFought;

            status +=
                " " +
                leader.DisplayName +
                " survives as a separate unit.";
        }
    }

    private void TryOpenCommandAbilities()
    {
        if (phase != Phase.Command ||
            selectedSquad == null)
        {
            status =
                "Select one of your units in the Command phase first.";
            return;
        }

        SquadController unit =
            selectedSquad.JoinedActionController();

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        if (FactionRuleSystem.UnitOrLeaderHasRule(
                unit,
                "Word of the Phoenix") &&
            unit.AttachedLeader != null &&
            unit.DestroyedModelTokens().Count > 0)
        {
            options.Add(
                new RuleChoiceOption(
                    "Word of the Phoenix",
                    () =>
                    {
                        CloseRuleChoice();

                        if (!IsXcomMode)
                        {
                            SelectSquadForAction(
                                unit
                            );

                            manualRestoreEditMode = true;
                            manualWoundEditMode = false;
                            manualRestoreDeadIndex = 0;

                            QueueTraditionalRuleAlert(
                                "WORD OF THE PHOENIX",
                                unit.DisplayName +
                                ": resolve the initial D6 and any follow-up D3+1 entirely yourself. If models return, use RESTORE EDIT to choose and return exactly the models your tabletop result permits.",
                                1
                            );

                            return;
                        }

                        int test =
                            DiceRoller.RollD6(
                                "Word of the Phoenix: " +
                                unit.DisplayName
                            );

                        if (test < 2)
                        {
                            status =
                                "WORD OF THE PHOENIX: rolled 1  -  no models return.";
                            return;
                        }

                        int count =
                            RollTabletopD3(
                                "Word of the Phoenix returned models"
                            ) + 1;

                        int returned =
                            ReanimateFullModels(
                                unit,
                                count,
                                true
                            );

                        status =
                            "WORD OF THE PHOENIX: returned " +
                            returned +
                            " Bodyguard model(s).";
                    }
                )
            );
        }

        bool hasTears =
            FactionRuleSystem.UnitOrLeaderHasRule(
                unit,
                "Tears of Isha"
            );

        if (hasTears)
        {
            List<SquadController> wraiths =
                squads
                    .Where(
                        target =>
                            target != null &&
                            !target.IsAttachedLeader &&
                            target.IsAlive &&
                            target.IsOnBattlefield &&
                            target.FactionId ==
                                unit.FactionId &&
                            target.HasKeyword(
                                "wraith construct") &&
                            !target.TearsOfIshaUsedThisTurn &&
                            JoinedDistance(
                                unit,
                                target
                            ) <= 6.001f
                    )
                    .ToList();

            foreach (SquadController wraith
                in wraiths)
            {
                SquadController captured = wraith;

                options.Add(
                    new RuleChoiceOption(
                        "Tears of Isha: " +
                        captured.DisplayName,
                        () =>
                        {
                            CloseRuleChoice();

                            captured.TearsOfIshaUsedThisTurn =
                                true;

                            if (!IsXcomMode)
                            {
                                SelectSquadForAction(
                                    captured
                                );

                                if (captured.DestroyedModelTokens().Count > 0)
                                {
                                    manualRestoreEditMode = true;
                                    manualWoundEditMode = false;
                                    manualRestoreDeadIndex = 0;

                                    QueueTraditionalRuleAlert(
                                        "TEARS OF ISHA",
                                        captured.DisplayName +
                                        ": this use returns a destroyed model. Choose the correct model yourself with RESTORE EDIT and return it at the state required by the tabletop rule.",
                                        0
                                    );
                                }
                                else
                                {
                                    manualWoundEditMode = true;
                                    manualRestoreEditMode = false;

                                    QueueTraditionalRuleAlert(
                                        "TEARS OF ISHA",
                                        captured.DisplayName +
                                        ": resolve the D3 healing roll yourself, then apply the exact number of restored wounds with WOUND EDIT.",
                                        1
                                    );
                                }

                                return;
                            }

                            if (captured.DestroyedModelTokens().Count > 0)
                            {
                                int returned =
                                    ReanimateFullModels(
                                        captured,
                                        1
                                    );

                                status =
                                    "TEARS OF ISHA: returned " +
                                    returned +
                                    " destroyed model.";
                            }
                            else
                            {
                                int amount =
                                    RollTabletopD3(
                                        "Tears of Isha: " +
                                        captured.DisplayName
                                    );

                                int healed =
                                    captured.HealWounds(
                                        amount
                                    );

                                status =
                                    "TEARS OF ISHA: healed " +
                                    healed +
                                    " wound(s).";
                            }
                        }
                    )
                );
            }
        }

        if (options.Count == 0)
        {
            status =
                "No currently usable Command abilities were found on the selected unit.";
            return;
        }

        options.Add(
            new RuleChoiceOption(
                "Close",
                CloseRuleChoice
            )
        );

        OpenRuleChoice(
            "COMMAND ABILITIES",
            unit.DisplayName +
            "  -  choose an available Command-phase ability.",
            options
        );
    }

    private int ReanimateFullModels(
        SquadController unit,
        int count,
        bool excludeSupportWeapons = false)
    {
        if (unit == null ||
            count <= 0 ||
            !unit.IsOnBattlefield ||
            unit.LivingModels <= 0)
        {
            return 0;
        }

        int returned = 0;

        while (returned < count)
        {
            ModelToken dead =
                unit.DestroyedModelTokens()
                    .FirstOrDefault(
                        model =>
                            !excludeSupportWeapons ||
                            (model.RoleName ?? "").IndexOf(
                                "Support Weapon",
                                System.StringComparison.OrdinalIgnoreCase
                            ) < 0
                    );

            if (dead == null)
                break;

            Vector3 position;

            if (!TryFindReanimationPosition(
                    unit,
                    dead,
                    out position))
            {
                break;
            }

            dead.Revive(
                dead.MaxWounds,
                position
            );

            returned++;
        }

        unit.RefreshVisuals();
        RefreshObjectiveDisplays();

        return returned;
    }

    private void TryUseSwiftAsTheWind()
    {
        if (phase != Phase.Move ||
            selectedSquad == null ||
            selectedSquad.HasMoved)
        {
