    public bool FriendlyKeywordWithin(
        SquadController unit,
        string keywordA,
        string keywordB,
        float distance)
    {
        if (unit == null)
            return false;

        return squads.Any(
            other =>
                other != null &&
                other.IsAlive &&
                other.IsOnBattlefield &&
                other.FactionId ==
                    unit.FactionId &&
                other != unit &&
                other.HasKeyword(
                    keywordA) &&
                other.HasKeyword(
                    keywordB) &&
                JoinedDistance(
                    other,
                    unit
                ) <=
                    distance + 0.001f
        );
    }

    private List<SquadController> EngagedEnemies(
        SquadController unit)
    {
        if (unit == null)
            return new List<SquadController>();

        return squads
            .Where(
                other =>
                    other != null &&
                    other.IsAlive &&
                    other.IsOnBattlefield &&
                    !other.IsAttachedLeader &&
                    other.FactionId !=
                        unit.FactionId &&
                    JoinedDistance(
                        unit,
                        other
                    ) <=
                        EngagementRange +
                        0.05f
            )
            .ToList();
    }

    private PhaseSnapshot CurrentPhaseSnapshot()
    {
        switch (phase)
        {
            case Phase.Command:
                return PhaseSnapshot.Command;
            case Phase.Move:
                return PhaseSnapshot.Move;
            case Phase.Shoot:
                return PhaseSnapshot.Shoot;
            case Phase.Charge:
                return PhaseSnapshot.Charge;
            case Phase.Fight:
                return PhaseSnapshot.Fight;
            default:
                return PhaseSnapshot.End;
        }
    }

    public void RecordModelDestroyed(
        ModelToken model,
        SquadController attacker)
    {
        Core11CheckDestroyedTransportForEmergencyDisembark(model);

        if (model == null ||
            model.Squad == null)
        {
            return;
        }

        DestroyedModelRecord record =
            new DestroyedModelRecord
            {
                Model = model,
                Unit = model.Squad,
                Attacker = attacker,
                Position = model.transform.position,
                Phase = CurrentPhaseSnapshot(),
                HadFought = model.Squad.HasFought
            };

        destroyedModelsThisPhase.Add(
            record
        );

        if (missionSystem != null)
        {
            missionSystem.RecordModelDestroyed(
                model
            );
        }

        SquadController unit =
            model.Squad;

        if (aeldariRules != null &&
            attacker != null &&
            attacker.FactionId !=
                unit.FactionId &&
            aeldariRules.DetachmentIs(
                unit.FactionId,
                AeldariDetachment.SpiritConclave
            ) &&
            unit.HasKeyword("asuryani") &&
            unit.HasKeyword("psyker"))
        {
            SquadController marked =
                attacker.JoinedActionController();

            marked.AeldariVengefulDeadTokens++;

            AppendBattleLog(
                "AELDARI",
                "Vengeful Dead",
                marked.DisplayName +
                " gained a Vengeful Dead token after destroying an Asuryani Psyker model."
            );
        }

        if (unit.LivingModels == 0 &&
            !destroyedUnitsRecordedThisPhase.Contains(
                unit))
        {
            destroyedUnitsRecordedThisPhase.Add(
                unit
            );

            destroyedUnitsThisPhase.Add(
                new DestroyedUnitRecord
                {
                    Unit = unit,
                    Attacker = attacker,
                    LastPosition =
                        model.transform.position,
                    FactionId = unit.FactionId,
                    Phase = CurrentPhaseSnapshot()
                }
            );

            if (missionSystem != null)
            {
                missionSystem.RecordUnitDestroyed(
                    unit,
                    attacker
                );
            }
        }
    }

    private List<DestroyedModelRecord>
        DestroyedModelsForUnitThisPhase(
            SquadController unit)
    {
        return destroyedModelsThisPhase
            .Where(
                record =>
                    record != null &&
                    record.Unit == unit
            )
            .ToList();
    }

    private bool TryUseConqueringTyrant()
    {
        if (selectedSquad == null ||
            factionRules == null ||
            phase != Phase.Shoot)
        {
            return false;
        }

        SquadController unit =
            selectedSquad.JoinedActionController();

        if (!factionRules.IsNecrons(
                unit.FactionId) ||
            unit.HasShot ||
            unit.IsBattleShocked ||
            unit.TargetedByFactionStratagemThisPhase ||
            GetCommandPoints(
                unit.FactionId
            ) < 1)
        {
            status =
                "Protocol of the Conquering Tyrant is not available for the selected unit.";
            return false;
        }

        if (!SpendFactionStratagemCP(
                unit,
                1,
                "Protocol of the Conquering Tyrant"))
        {
            return false;
        }

        unit.FactionConqueringTyrantActive = true;

        status =
            "PROTOCOL OF THE CONQUERING TYRANT: at half range, " +
            unit.DisplayName +
            (unit.AttachedLeader != null &&
             unit.AttachedLeader.IsAlive &&
             unit.AttachedLeader.HasKeyword("necrons") &&
             unit.AttachedLeader.HasKeyword("character")
                ? " re-rolls failed Hit rolls."
                : " re-rolls Hit rolls of 1.");

        showStratagemMenu = false;
        return true;
    }

    private void OfferUndyingLegions(
        InteractiveAttackController resolvedAttack)
    {
        SquadController target =
            resolvedAttack.Target != null
            ? resolvedAttack.Target.JoinedActionController()
            : null;

        int destroyed =
            resolvedAttack.DestroyedModels.Count;

        bool eligible =
            target != null &&
            target.IsAlive &&
            target.IsOnBattlefield &&
            target.LivingModels > 0 &&
            destroyed > 0 &&
            factionRules != null &&
            factionRules.IsNecrons(
                target.FactionId) &&
            !target.TargetedByFactionStratagemThisPhase &&
            GetCommandPoints(
                target.FactionId
            ) >= 1;

        if (!eligible)
        {
            ContinuePostAttackFlow();
            return;
        }

        OpenRuleChoice(
            "PROTOCOL OF THE UNDYING LEGIONS",
            target.DisplayName +
            " lost one or more models to this attack. Activate Reanimation Protocols now?",
            new[]
            {
                new RuleChoiceOption(
                    "Reanimate (1 CP)",
                    () =>
                    {
                        CloseRuleChoice();

                        if (!SpendFactionStratagemCP(
                                target,
                                1,
                                "Protocol of the Undying Legions"))
                        {
                            ContinuePostAttackFlow();
                            return;
                        }

                        if (!IsXcomMode)
                        {
                            SelectSquadForAction(
                                target
                            );

                            manualRestoreEditMode = true;
                            manualWoundEditMode = false;
                            manualRestoreDeadIndex = 0;

                            QueueTraditionalRuleAlert(
                                "PROTOCOL OF THE UNDYING LEGIONS",
                                target.DisplayName +
                                ": resolve the Reanimation roll and any Character bonus yourself, then use WOUND EDIT / RESTORE EDIT to apply exactly what the tabletop result permits.",
                                1,
                                ContinuePostAttackFlow
                            );

                            return;
                        }

                        int amount =
                            RollTabletopD3(
                                "Undying Legions: " +
                                target.DisplayName
                            );

                        if (target.AttachedLeader != null &&
                            target.AttachedLeader.IsAlive &&
                            target.AttachedLeader.HasKeyword(
                                "necrons") &&
                            target.AttachedLeader.HasKeyword(
                                "character"))
                        {
                            amount += 1;
                        }

                        int restored =
                            ReanimateUnit(
                                target,
                                amount
                            );

                        status =
                            "UNDYING LEGIONS: restored " +
                            restored +
                            " wound(s).";

                        ContinuePostAttackFlow();
                    }
                ),
                new RuleChoiceOption(
                    "Skip",
                    () =>
                    {
                        CloseRuleChoice();
                        ContinuePostAttackFlow();
                    }
                )
            }
        );
    }

    private void OfferVengefulStars(
        InteractiveAttackController resolvedAttack)
    {
        if (resolvedAttack.Mode !=
                AttackMode.Ranged ||
            resolvedAttack.Target == null ||
            resolvedAttack.Attacker == null)
        {
            ContinuePostAttackFlow();
            return;
        }

        DestroyedUnitRecord destroyed =
            destroyedUnitsThisPhase
                .LastOrDefault(
                    record =>
                        record != null &&
                        record.Unit ==
                            resolvedAttack.Target
                                .JoinedActionController()
                );

        if (destroyed == null ||
            factionRules == null ||
            !factionRules.IsNecrons(
                destroyed.FactionId))
        {
            ContinuePostAttackFlow();
            return;
        }

        List<SquadController> eligible =
            squads
                .Where(
                    unit =>
                        unit != null &&
                        !unit.IsAttachedLeader &&
                        unit.IsAlive &&
                        unit.IsOnBattlefield &&
                        unit.FactionId ==
                            destroyed.FactionId &&
                        unit.HasKeyword("character") &&
                        HorizontalDistance(
                            unit.CurrentCentre(),
                            destroyed.LastPosition
                        ) <= 6.001f &&
                        !unit.TargetedByFactionStratagemThisPhase &&
                        GetCommandPoints(
                            unit.FactionId
                        ) >= 2
                )
                .ToList();

        if (eligible.Count == 0)
        {
            ContinuePostAttackFlow();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (SquadController unit
            in eligible)
        {
            SquadController captured = unit;

            options.Add(
                new RuleChoiceOption(
                    "Vengeful Stars: " +
                    captured.DisplayName +
                    " (2 CP)",
                    () =>
                    {
                        CloseRuleChoice();

                        if (!SpendFactionStratagemCP(
                                captured,
                                2,
                                "Protocol of the Vengeful Stars"))
                        {
                            ContinuePostAttackFlow();
                            return;
                        }

                        BeginSpecialShoot(
                            captured,
                            resolvedAttack.Attacker,
                            "Protocol of the Vengeful Stars",
                            ContinuePostAttackFlow
                        );
                    }
                )
            );
        }

        options.Add(
            new RuleChoiceOption(
                "Skip",
                () =>
                {
                    CloseRuleChoice();
                    ContinuePostAttackFlow();
                }
            )
        );

        OpenRuleChoice(
            "PROTOCOL OF THE VENGEFUL STARS",
            "A Necron unit was destroyed by this Shooting attack. An eligible nearby Necron Character can retaliate against the attacking unit.",
            options
        );
    }

    private void OfferPallOfDread(
        InteractiveAttackController resolvedAttack)
    {
        if (resolvedAttack.Target == null)
        {
            ContinuePostAttackFlow();
            return;
        }

        SquadController target =
            resolvedAttack.Target.JoinedActionController();

        DestroyedUnitRecord destroyed =
            destroyedUnitsThisPhase
                .LastOrDefault(
                    record =>
                        record != null &&
                        record.Unit == target
                );

        if (destroyed == null ||
            factionRules == null ||
            !UsesDevotedOfYnneadRules(
                target.FactionId) ||
            !target.HasKeyword("ynnari") ||
            target.TargetedByFactionStratagemThisPhase ||
            GetCommandPoints(
                target.FactionId
            ) < 1)
        {
            ContinuePostAttackFlow();
            return;
        }

        List<ObjectiveController> eligible =
            objectives
                .Where(
                    objective =>
                    {
                        string previous;

                        bool controlled =
                            objectiveControlAtPhaseStart.TryGetValue(
                                objective,
                                out previous
                            ) &&
                            previous ==
                                target.FactionId;

                        bool wasInRange =
                            destroyedModelsThisPhase.Any(
                                modelRecord =>
                                    modelRecord != null &&
                                    modelRecord.Unit == target &&
                                    HorizontalDistance(
                                        objective.transform.position,
                                        modelRecord.Position
                                    ) <=
                                        ObjectiveController.ControlRadius +
                                        0.001f
                            );

                        return
                            controlled &&
                            wasInRange;
                    }
                )
                .ToList();

        if (eligible.Count == 0)
        {
            ContinuePostAttackFlow();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        for (int i = 0;
             i < eligible.Count;
             i++)
        {
            ObjectiveController objective =
                eligible[i];

            int number = i + 1;

            options.Add(
                new RuleChoiceOption(
                    "Pall of Dread: Objective " +
                    number +
                    " (1 CP)",
                    () =>
                    {
                        CloseRuleChoice();

                        if (!SpendFactionStratagemCP(
                                target,
                                1,
                                "Pall of Dread"))
                        {
                            ContinuePostAttackFlow();
                            return;
                        }

                        objective.SecureFor(
                            target.FactionId
                        );

                        objective.RefreshStatus(
                            squads
                        );

                        status =
                            "PALL OF DREAD: objective remains secured until the opponent's Level of Control exceeds yours at the end of a phase.";

                        ContinuePostAttackFlow();
                    }
                )
            );
        }

        options.Add(
            new RuleChoiceOption(
                "Skip",
                () =>
                {
                    CloseRuleChoice();
                    ContinuePostAttackFlow();
                }
            )
        );

        OpenRuleChoice(
            "PALL OF DREAD",
            "The destroyed Ynnari unit was within an objective you controlled at the end of the previous phase.",
            options
        );
    }

    private void ResolveStormOfWhispers(
        InteractiveAttackController resolvedAttack)
    {
        if (resolvedAttack.Mode ==
                AttackMode.Ranged &&
            resolvedAttack.TotalHits > 0 &&
            resolvedAttack.Attacker != null &&
            resolvedAttack.Target != null &&
            FactionRuleSystem.UnitOrLeaderHasRule(
                resolvedAttack.Attacker,
                "Storm of Whispers"))
        {
            ResolveImmediateBattleShock(
                resolvedAttack.Target,
                "Storm of Whispers"
            );
        }

        ContinuePostAttackFlow();
    }

    private void ResolveImmediateBattleShock(
        SquadController unit,
        string label)
    {
        if (unit == null ||
            !unit.IsAlive)
        {
            return;
        }

        SquadController target =
            unit.JoinedActionController();

        if (!IsXcomMode)
        {
            traditionalBattleShockQueue.Clear();
            traditionalBattleShockUnit = target;
            traditionalBattleShockLabel =
                label;
            traditionalBattleShockPending =
                true;

                        // WARBOARD_V46_FORCED_TRADITIONAL_BATTLESHOCK_DICE
            int forcedDiceCount =
                WarboardFactionExtensionHub
                    .BattleShockDice(
                        this,
                        target
                    );

            OpenTraditionalDicePrompt(
                forcedDiceCount
            );

            status =
                label +
                ": " +
                target.DisplayName +
                " must take a Battle-shock test. Resolve " +
                forcedDiceCount +
                "D6 manually and mark PASS or FAIL.";

            AppendBattleLog(
                "BATTLE-SHOCK",
                target.DisplayName,
                label +
                " triggered a manual Traditional Battle-shock test."
            );

            return;
        }

        int leadership =
            EffectiveLeadership(
                target
            );

                // WARBOARD_V46_FORCED_BATTLESHOCK_DICE
        int standardBattleShockDice =
            WarboardFactionExtensionHub
                .BattleShockDice(
                    this,
                    target
                );

        int roll =
            standardBattleShockDice >= 3
            ? DiceRoller.RollDice(
                standardBattleShockDice,
                6,
                label +
                ": " +
                target.DisplayName
              ).Total
            : DiceRoller.Roll2D6(
                label +
                ": " +
                target.DisplayName
              );

        bool passed =
            roll >= leadership;

        target.SetBattleShocked(
            !passed,
            roll
        );

        AppendBattleLog(
            "BATTLE-SHOCK",
            target.DisplayName,
            label +
            "  |  Leadership " +
            leadership +
            "+  |  roll " +
            roll +
            "  ->  " +
            (passed
                ? "PASS"
                : "FAIL  -  BATTLE-SHOCKED (OC 0)")
        );

        status =
            label +
            ": " +
            target.DisplayName +
            " rolled " +
            roll +
            " vs Ld " +
            leadership +
            (passed
                ? "  -  passed."
                : "  -  BATTLE-SHOCKED.");
    }

    private bool ChargingModelCanReachDistance(
        SquadController attacker,
        ModelToken movingModel,
        SquadController target,
        Vector3 originalStart,
        float chargeDistance,
        float requiredDistance)
    {
        Vector3 current =
            movingModel.transform.position;

        float startingDistance =
            DistancePointToSquad(
                originalStart,
                target
            );

        List<Vector3> candidates =
            BuildChargeDestinationCandidates(
                movingModel,
                target,
                originalStart,
                chargeDistance
            );

        foreach (Vector3 candidate
            in candidates)
        {
            if (DistancePointToSquad(
                    candidate,
                    target
                ) >
                requiredDistance + 0.05f)
            {
                continue;
            }

            if (!ChargeDestinationIsLocallyLegal(
                    attacker,
                    movingModel,
                    target,
                    originalStart,
                    candidate,
                    chargeDistance,
                    startingDistance))
            {
                continue;
            }

            movingModel.transform.position =
                candidate;

            Physics.SyncTransforms();

            bool valid =
                attacker.IsCoherent() &&
                AllModelsInsideBoard(
                    attacker
                ) &&
                AllModelsHaveLegalPlacement(
                    attacker
                ) &&
                !IsEngagedWithNonTargetEnemy(
                    attacker,
                    target
                );

            movingModel.transform.position =
                current;

            Physics.SyncTransforms();

            if (valid)
                return true;
        }

        return false;
    }

    private bool FormationTranslationCandidateIsLegal(
        SquadController attacker,
        SquadController target,
        Vector3 delta)
    {
        if (HorizontalMagnitude(delta) >
            0.001f)
        {
            foreach (ModelToken model
                in JoinedModels(attacker))
            {
                Vector3 start =
                    model.transform.position;

                Vector3 destination =
                    start +
                    delta;

                if (!InsideBoard(destination))
                    return false;

                // Every charging model must end closer to a charge target.
                float before =
                    DistancePointToSquad(
                        start,
                        target
                    );

                float after =
                    DistancePointToSquad(
                        destination,
                        target
                    );

                if (after >=
                    before - 0.001f)
                {
                    return false;
                }

                // Do not cross terrain/enemy model footprints.
                bool canPassEnemies =
                    aeldariRules != null &&
                    aeldariRules
                        .CanMoveThroughEnemyModelsWhenCharging(
                            attacker
                        );

                if (!CombatMovePathIsClear(
                    model,
                    start,
                    destination,
                    canPassEnemies
                ))
                {
                    return false;
                }

                // Final position may not overlap an enemy model.
                foreach (ModelToken enemy
                    in JoinedModels(target))
                {
                    if (HorizontalDistance(
                            destination,
                            enemy.transform.position
                        ) <
                        MinimumModelSeparation(
                            model,
                            enemy
                        ))
                    {
                        return false;
                    }
                }

                // Nor may it overlap models in any other enemy unit.
                foreach (SquadController other
                    in squads)
                {
                    if (other == target ||
                        other == null ||
                        !other.IsOnBattlefield ||
                        other.FactionId ==
                            attacker.FactionId ||
                        !other.IsAlive)
                    {
                        continue;
                    }

                    foreach (ModelToken enemy
                        in other.LivingModelTokens())
                    {
                        if (HorizontalDistance(
                                destination,
                                enemy.transform.position
                            ) <
                            MinimumModelSeparation(
                                model,
                                enemy
                            ))
                        {
                            return false;
                        }
                    }
                }
            }
        }

        // A rigid translation preserves the attacker's internal distances, so
        // coherency remains exactly what it was before the charge. The current
        // unit should already be coherent when selected to charge.
        if (!attacker.IsCoherent())
            return false;

        float translatedDistance =
            DistanceSquadToTargetAfterTranslation(
                attacker,
                target,
                delta
            );

        if (translatedDistance >
            EngagementRange + 0.05f)
        {
            return false;
        }

        // Check that this translation does not bring the charging unit into
        // Engagement Range of an enemy that was not selected as a target.
        foreach (SquadController other
            in squads)
        {
            if (other == target ||
                other.IsAttachedLeader ||
                other.FactionId ==
                    attacker.FactionId ||
                !other.IsAlive)
            {
                continue;
            }

            if (DistanceSquadToTargetAfterTranslation(
                    attacker,
                    other,
                    delta
                ) <=
                EngagementRange + 0.05f)
            {
                return false;
            }
        }

        return true;
    }

    private bool OfferHeraldOfYnnead()
    {
        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (SquadController source
            in squads)
        {
            if (source == null ||
                source.IsAttachedLeader ||
                !source.IsAlive ||
                !source.IsOnBattlefield ||
                !FactionRuleSystem.UnitOrLeaderHasRule(
                    source,
                    "Herald of Ynnead"))
            {
                continue;
            }

            foreach (SquadController enemy
                in EngagedEnemies(source))
            {
                SquadController capturedSource =
                    source;

                SquadController capturedEnemy =
                    enemy;

                options.Add(
                    new RuleChoiceOption(
                        capturedSource.DisplayName +
                        " marks " +
                        capturedEnemy.DisplayName,
                        () =>
                        {
                            CloseRuleChoice();

                            heraldOfYnneadTarget =
                                capturedEnemy
                                    .JoinedActionController();

                            heraldOfYnneadFaction =
                                capturedSource.FactionId;

                            status =
                                "HERALD OF YNNEAD: friendly Aeldari re-roll Wound rolls of 1 against " +
                                capturedEnemy.DisplayName +
                                " this Fight phase.";

                            OfferLethalReprisal();
                        }
                    )
                );
            }
        }

        if (options.Count == 0)
            return false;

        options.Add(
            new RuleChoiceOption(
                "Skip Herald of Ynnead",
                () =>
                {
                    CloseRuleChoice();
                    OfferLethalReprisal();
                }
            )
        );

        OpenRuleChoice(
            "HERALD OF YNNEAD",
            "At the start of the Fight phase, select one enemy unit within Engagement Range of the Herald.",
            options
        );

        return true;
    }

    public bool HasHeraldOfYnneadReroll(
        SquadController attacker,
        SquadController target)
    {
        if (attacker == null ||
            target == null ||
            heraldOfYnneadTarget == null)
        {
            return false;
        }

        return
            attacker.FactionId ==
                heraldOfYnneadFaction &&
            attacker.HasOwnKeywordValue(
                "aeldari") &&
            target.JoinedActionController() ==
                heraldOfYnneadTarget;
    }

    private void OfferLethalReprisal()
    {
        List<SquadController> reprisalEligible =
            squads
                .Where(
                    unit =>
                        unit != null &&
                        !unit.IsAttachedLeader &&
                        unit.IsAlive &&
                        unit.IsOnBattlefield &&
                        factionRules != null &&
                        UsesDevotedOfYnneadRules(
                            unit.FactionId) &&
                        unit.HasKeyword("ynnari") &&
                        !unit.HasKeyword("titanic") &&
                        unit.IsBelowStartingStrength()
                )
                .ToList();

        if (reprisalEligible.Count == 0)
        {
            BeginFightSequence();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (SquadController unit
            in reprisalEligible)
        {
            SquadController captured = unit;

            options.Add(
                new RuleChoiceOption(
                    "Lethal Reprisal: " +
                    captured.DisplayName,
                    () =>
                    {
                        CloseRuleChoice();
                        captured.TemporaryFightsFirst = true;

                        status =
                            "LETHAL REPRISAL: " +
                            captured.DisplayName +
                            " has Fights First until end of phase.";

                        BeginFightSequence();
                    }
                )
            );
        }

        options.Add(
            new RuleChoiceOption(
                "Skip Lethal Reprisal",
                () =>
                {
                    CloseRuleChoice();
                    BeginFightSequence();
                }
            )
        );

        OpenRuleChoice(
            "STRENGTH FROM DEATH  -  LETHAL REPRISAL",
            "At the start of the Fight phase, select one below-Starting-Strength Ynnari unit to gain Fights First.",
            options
        );
    }

    private float DistancePointToClosestEnemyModel(
        Vector3 point,
        string faction)
    {
        float best =
            float.MaxValue;

        foreach (SquadController unit
            in squads)
        {
            if (unit == null ||
                !unit.IsAlive ||
                !unit.IsOnBattlefield ||
                unit.IsAttachedLeader ||
                unit.FactionId ==
                    faction)
            {
                continue;
            }

            foreach (ModelToken model
                in JoinedModels(unit))
            {
                if (model == null ||
                    !model.IsAlive)
                {
                    continue;
                }

                best =
                    Mathf.Min(
                        best,
                        HorizontalDistance(
                            point,
                            model.transform.position
                        )
                    );
            }
        }

        return best;
    }

    private SquadController FindNearestEnemy(SquadController squad)
    {
        SquadController best = null;
        float bestDistance = float.MaxValue;

        foreach (SquadController other in squads)
        {
            if (!other.IsAlive ||
                other.IsAttachedLeader ||
                other.FactionId == squad.FactionId)
            {
                continue;
            }

            float d =
                JoinedDistance(
                    squad,
                    other
                );

            if (d < bestDistance)
            {
                bestDistance = d;
                best = other;
            }
        }

        return best;
    }

    private float DistancePointToSquad(
        Vector3 point,
        SquadController target)
    {
        float best =
            float.MaxValue;

        foreach (ModelToken model
            in target.LivingModelTokens())
        {
            best =
                Mathf.Min(
                    best,
                    HorizontalDistance(
                        point,
                        model.transform.position
                    )
                );
        }

        return best ==
            float.MaxValue
            ? 999f
            : best;
    }

    private float JoinedDistance(
        SquadController a,
        SquadController b)
    {
        float best =
            float.MaxValue;

        foreach (ModelToken modelA
            in JoinedModels(a))
        {
            foreach (ModelToken modelB
                in JoinedModels(b))
            {
                best =
                    Mathf.Min(
                        best,
                        HorizontalDistance(
                            modelA.transform.position,
                            modelB.transform.position
                        )
                    );
            }
        }

        return best ==
            float.MaxValue
            ? 999f
            : best;
    }

    private bool IsEngaged(SquadController squad)
    {
        return squads.Any(
            other =>
                other != squad &&
                other.IsAlive &&
                other.FactionId != squad.FactionId &&
                JoinedDistance(squad, other) <= EngagementRange
        );
    }

    public bool IsUnitEngagedPublic(
        SquadController squad)
    {
        return
            squad != null &&
            IsEngaged(squad);
    }

    public bool UnitsAreEngaged(
        SquadController a,
        SquadController b)
    {
        return
            CoreRules11Geometry
                .UnitsEngaged(a, b);
    }

    public bool ModelCanSeeUnit(
        ModelToken shooter,
        SquadController target)
    {
        return ModelHasLineOfSight(
            shooter,
            target
        );
    }

    private bool ModelHasLineOfSight(
        ModelToken shooter,
        SquadController target)
    {
        if (shooter == null ||
            !shooter.IsAlive)
        {
            return false;
        }

        foreach (ModelToken targetModel
            in JoinedModels(target))
        {
            if (ModelHasLineOfSightToModel(
                shooter,
                targetModel))
            {
                return true;
            }
        }

        return false;
    }

    public bool ModelCanSeeModel(
        ModelToken shooter,
        ModelToken targetModel)
    {
        return ModelHasLineOfSightToModel(
            shooter,
            targetModel
        );
    }

    private bool ModelHasLineOfSightToModel(
        ModelToken shooter,
        ModelToken targetModel)
    {
        return Core11CanSeeModel(shooter, targetModel);
    }

    private ModelToken ClosestJoinedModelTo(
        SquadController squad,
        Vector3 point)
    {
        ModelToken bestModel = null;
        float best =
            float.MaxValue;

        foreach (ModelToken model
            in JoinedModels(squad))
        {
            float distance =
                HorizontalDistance(
                    point,
                    model.transform.position
                );

            if (distance < best)
            {
                best = distance;
                bestModel = model;
            }
        }

        return bestModel;
    }

    private float ModelDistanceToSquad(
        ModelToken model,
        SquadController target)
    {
        float best =
            float.MaxValue;

        foreach (ModelToken targetModel
            in JoinedModels(target))
        {
            best =
                Mathf.Min(
                    best,
                    HorizontalDistance(
                        model.transform.position,
                        targetModel.transform.position
                    )
                );
        }

        return best ==
            float.MaxValue
            ? 999f
            : best;
    }

    private void ClearPhaseDestructionRecords()
    {
        destroyedModelsThisPhase.Clear();
        destroyedUnitsThisPhase.Clear();
        destroyedUnitsRecordedThisPhase.Clear();
    }

    private void BuildEndPhaseFlow()
    {
        endPhaseFlowQueue.Clear();
        endPhaseFlowRunning = true;

        if (phase == Phase.Command &&
            factionRules != null &&
            factionRules.IsNecrons(
                activeFaction))
        {
            endPhaseFlowQueue.Enqueue(
                OfferNormalReanimationProtocols
            );
        }

        if (phase == Phase.Move)
        {
            endPhaseFlowQueue.Enqueue(
                OfferFireOverwatch
            );
        }

        if (phase == Phase.Shoot)
        {
            endPhaseFlowQueue.Enqueue(
                OfferDeathAnswersDeath
            );

            endPhaseFlowQueue.Enqueue(
                OfferLethalIntent
            );
        }

        endPhaseFlowQueue.Enqueue(
            OfferEternalRevenant
        );

        endPhaseFlowQueue.Enqueue(
            OfferResurrectionOrb
        );

        if (phase == Phase.End)
        {
            endPhaseFlowQueue.Enqueue(
                OfferWindriderHostExtraction
            );

            endPhaseFlowQueue.Enqueue(
                OfferVeilOfDarkness
            );
        }
    }

    private void ContinueEndPhaseFlow()
    {
        if (!endPhaseFlowRunning)
            return;

        if (showRuleChoiceWindow ||
            specialMoveSquad != null ||
            specialShootUnit != null ||
            interactiveAttack != null ||
            TraditionalStateResolutionPending())
        {
            return;
        }

        if (endPhaseFlowQueue.Count > 0)
        {
            System.Action next =
                endPhaseFlowQueue.Dequeue();

            next();
            return;
        }

        endPhaseFlowRunning = false;
        CompletePhaseTransition();
    }

    private void OfferNormalReanimationProtocols()
    {
        List<SquadController> eligible =
            squads
                .Where(
                    unit =>
                        unit != null &&
                        !unit.IsAttachedLeader &&
                        unit.FactionId ==
                            activeFaction &&
                        unit.IsAlive &&
                        unit.IsOnBattlefield &&
                        unit.LivingModels > 0 &&
                        unit.HasAnyLostWoundsOrModels() &&
                        FactionRuleSystem
                            .UnitOrLeaderHasRule(
                                unit,
                                "Reanimation Protocols"
                            )
                )
                .ToList();

        if (eligible.Count == 0)
        {
            status =
                "Reanimation Protocols: no eligible damaged units.";

            ContinueEndPhaseFlow();
            return;
        }

        if (IsXcomMode)
        {
            ResolveNextXcomReanimation(
                eligible
            );

            return;
        }

        BeginTraditionalReanimation(
            eligible
        );
    }

    private void ResolveNextXcomReanimation(
        List<SquadController> remaining)
    {
        if (remaining == null)
        {
            ContinueEndPhaseFlow();
            return;
        }

        remaining =
            remaining
                .Where(
                    unit =>
                        unit != null &&
                        unit.IsAlive &&
                        unit.IsOnBattlefield &&
                        unit.HasAnyLostWoundsOrModels()
                )
                .ToList();

        if (remaining.Count == 0)
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (SquadController unit
            in remaining)
        {
            SquadController captured =
                unit;

            options.Add(
                new RuleChoiceOption(
                    captured.DisplayName +
                    "  -  " +
                    Mathf.Max(
                        0,
                        captured.StartingModels -
                        captured.LivingModels
                    ) +
                    " model(s) lost",
                    () =>
                    {
                        CloseRuleChoice();

                        List<SquadController> next =
                            remaining
                                .Where(
                                    value =>
                                        value != captured
                                )
                                .ToList();

                        ResolveXcomReanimationForUnit(
                            captured,
                            next
                        );
                    }
                )
            );
        }

        OpenRuleChoice(
            "REANIMATION PROTOCOLS AVAILABLE",
            "Select the Necron unit to resolve next. Warboard makes the Reanimation roll automatically; placement and genuine optional choices remain yours.",
            options.ToArray()
        );
    }

    private void ResolveXcomReanimationForUnit(
        SquadController unit,
        List<SquadController> remaining)
    {
        if (unit == null)
        {
            ResolveNextXcomReanimation(
                remaining
            );
            return;
        }

        int rolled =
            RollTabletopD3(
                "Reanimation Protocols: " +
                unit.DisplayName
            );

        System.Action<int> resolve =
            value =>
            {
                int restored =
                    ReanimateUnit(
                        unit,
                        value
                    );

                AppendBattleLog(
                    "REANIMATION",
                    unit.DisplayName,
                    "D3 result " +
                    value +
                    "  ->  " +
                    restored +
                    " wound(s) restored."
                );

                status =
                    "REANIMATION PROTOCOLS: " +
                    unit.DisplayName +
                    " restored " +
                    restored +
                    " wound(s).";

                ResolveNextXcomReanimation(
                    remaining
                );
            };

        bool canReroll =
            FactionRuleSystem
                .UnitOrLeaderHasRule(
                    unit,
                    "Their Number Is Legion"
                );

        if (!canReroll)
        {
            resolve(rolled);
            return;
        }

        OpenRuleChoice(
            "THEIR NUMBER IS LEGION",
            unit.DisplayName +
            " generated " +
            rolled +
            " Reanimation point(s). Keep it or use the optional re-roll?",
            new[]
            {
                new RuleChoiceOption(
                    "Keep " +
                    rolled,
                    () =>
                    {
                        CloseRuleChoice();
                        resolve(rolled);
                    }
                ),
                new RuleChoiceOption(
                    "Re-roll automatically",
                    () =>
                    {
                        CloseRuleChoice();

                        int rerolled =
                            RollTabletopD3(
                                "Their Number Is Legion: " +
                                unit.DisplayName
                            );

                        resolve(rerolled);
                    }
                )
            }
        );
    }

    private void ResolveNextNormalReanimation(
        List<SquadController> eligible,
        int index)
    {
        if (eligible == null ||
            index >= eligible.Count)
        {
            ContinueEndPhaseFlow();
            return;
        }

        SquadController unit =
            eligible[index];

        if (unit == null ||
            !unit.IsAlive ||
            !unit.IsOnBattlefield ||
            unit.LivingModels <= 0 ||
            !unit.HasAnyLostWoundsOrModels())
        {
            ResolveNextNormalReanimation(
                eligible,
                index + 1
            );

            return;
        }

        int rolled =
            RollTabletopD3(
                "Reanimation Protocols: " +
                unit.DisplayName
            );

        bool canReroll =
            FactionRuleSystem
                .UnitOrLeaderHasRule(
                    unit,
                    "Their Number Is Legion"
                );

        System.Action<int> resolve =
            value =>
            {
                int restored =
                    ReanimateUnit(
                        unit,
                        value
                    );

                status =
                    "REANIMATION PROTOCOLS: " +
                    unit.DisplayName +
                    " restored " +
                    restored +
                    " wound(s) from D3=" +
                    value +
                    ".";

                ResolveNextNormalReanimation(
                    eligible,
                    index + 1
                );
            };

        if (!canReroll)
        {
            resolve(rolled);
            return;
        }

        OpenRuleChoice(
            "THEIR NUMBER IS LEGION",
            unit.DisplayName +
            " rolled " +
            rolled +
            " for Reanimation Protocols. Re-roll that D3?",
            new[]
            {
                new RuleChoiceOption(
                    "Keep " +
                    rolled,
                    () =>
                    {
                        CloseRuleChoice();
                        resolve(rolled);
                    }
                ),
                new RuleChoiceOption(
                    "Re-roll D3",
                    () =>
                    {
                        CloseRuleChoice();

                        int rerolled =
                            RollTabletopD3(
                                "Their Number Is Legion: " +
                                unit.DisplayName
                            );

                        resolve(rerolled);
                    }
                )
            }
        );
    }

    private void OfferFireOverwatch()
    {
        string defender =
            factions.FirstOrDefault(
                faction =>
                    faction != activeFaction
            );

        if (string.IsNullOrWhiteSpace(
                defender) ||
            GetCommandPoints(defender) < 1)
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (SquadController shooter
            in squads.Where(
                unit =>
                    unit != null &&
                    !unit.IsAttachedLeader &&
                    unit.FactionId == defender &&
                    unit.IsAlive &&
                    unit.IsOnBattlefield &&
                    !unit.HasKeyword("titanic") &&
                    !IsEngaged(unit) &&
                    !unit.TargetedByFactionStratagemThisPhase))
        {
            foreach (SquadController enemy
                in squads.Where(
                    unit =>
                        unit != null &&
                        !unit.IsAttachedLeader &&
                        unit.FactionId == activeFaction &&
                        unit.IsAlive &&
                        unit.IsOnBattlefield &&
                        !unit.FlittingShadowsActive &&
                        JoinedDistance(
                            shooter,
                            unit
                        ) <= 24.001f))
            {
                List<WeaponAttackSelection> legal =
                    GetEligibleRangedWeapons(
                        shooter,
                        enemy,
                        false
                    );

                if (legal.Count == 0)
                    continue;

                SquadController capturedShooter =
                    shooter;

                SquadController capturedEnemy =
                    enemy;

                options.Add(
                    new RuleChoiceOption(
                        capturedShooter.DisplayName +
                        " overwatches " +
                        capturedEnemy.DisplayName +
                        " (1 CP)",
                        () =>
                        {
                            CloseRuleChoice();

                            if (!SpendFactionStratagemCP(
                                    capturedShooter,
                                    1,
                                    "Fire Overwatch"))
                            {
                                ContinueEndPhaseFlow();
                                return;
                            }

                            capturedShooter.SnapShootingActive =
                                true;

                            BeginSpecialShoot(
                                capturedShooter,
                                capturedEnemy,
                                "Fire Overwatch",
                                () =>
                                {
                                    capturedShooter.SnapShootingActive =
                                        false;

                                    ContinueEndPhaseFlow();
                                }
                            );
                        }
                    )
                );
            }
        }

        if (options.Count == 0)
        {
            ContinueEndPhaseFlow();
            return;
        }

        options.Add(
            new RuleChoiceOption(
                "Skip Fire Overwatch",
                () =>
                {
                    CloseRuleChoice();
                    ContinueEndPhaseFlow();
                }
            )
        );

        OpenRuleChoice(
            "FIRE OVERWATCH",
            "End of the opponent's Movement phase. Select an eligible unengaged unit and one visible enemy within 24 inches. Snap Shooting only hits on unmodified 6s and cannot re-roll Hit rolls. Units protected by Flitting Shadows are excluded.",
            options
        );
    }

