    private void OfferLethalIntent()
    {
        string ynnariFaction =
            factions.FirstOrDefault(
                faction =>
                    faction != activeFaction &&
                    factionRules != null &&
                    UsesDevotedOfYnneadRules(
                        faction
                    )
            );

        if (string.IsNullOrWhiteSpace(
                ynnariFaction))
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<DestroyedUnitRecord> destroyed =
            destroyedUnitsThisPhase
                .Where(
                    record =>
                        record != null &&
                        record.FactionId ==
                            ynnariFaction &&
                        record.Unit != null &&
                        record.Unit.HasKeyword(
                            "ynnari")
                )
                .ToList();

        if (destroyed.Count == 0)
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<SquadController> eligible =
            squads
                .Where(
                    unit =>
                        unit != null &&
                        unit.IsAlive &&
                        unit.IsOnBattlefield &&
                        !unit.IsAttachedLeader &&
                        unit.FactionId ==
                            ynnariFaction &&
                        unit.HasKeyword("ynnari") &&
                        (unit.HasKeyword("infantry") ||
                         unit.HasKeyword("mounted")) &&
                        destroyed.Any(
                            record =>
                                JoinedModels(unit).Any(
                                    model =>
                                        HorizontalDistance(
                                            model.transform.position,
                                            record.LastPosition
                                        ) <= 6.001f
                                )
                        )
                )
                .ToList();

        if (eligible.Count == 0)
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (SquadController unit
            in eligible)
        {
            SquadController captured = unit;

            options.Add(
                new RuleChoiceOption(
                    "Lethal Intent: " +
                    captured.DisplayName,
                    () =>
                    {
                        CloseRuleChoice();

                        if (!IsXcomMode)
                        {
                            OpenTraditionalNumericPrompt(
                                "LETHAL INTENT",
                                captured.DisplayName +
                                " makes a D6+1 move. Resolve the roll yourself and enter the final movement distance.",
                                2,
                                7,
                                2,
                                1,
                                value =>
                                    BeginSpecialMove(
                                        captured,
                                        value,
                                        "Lethal Intent",
                                        ContinueEndPhaseFlow
                                    ),
                                ContinueEndPhaseFlow
                            );

                            return;
                        }

                        int move =
                            DiceRoller.RollD6(
                                "Lethal Intent: " +
                                captured.DisplayName
                            ) + 1;

                        BeginSpecialMove(
                            captured,
                            move,
                            "Lethal Intent",
                            ContinueEndPhaseFlow
                        );
                    }
                )
            );
        }

        options.Add(
            new RuleChoiceOption(
                "Skip",
                () =>
                {
                    CloseRuleChoice();
                    ContinueEndPhaseFlow();
                }
            )
        );

        OpenRuleChoice(
            "STRENGTH FROM DEATH  -  LETHAL INTENT",
            "A Ynnari unit was destroyed this Shooting phase. Select one eligible Ynnari Infantry/Mounted unit that was within 6 inches of a destroyed unit.",
            options
        );
    }

    private void OfferEternalRevenant()
    {
        List<DestroyedModelRecord> eligible =
            destroyedModelsThisPhase
                .Where(
                    record =>
                        record != null &&
                        record.Model != null &&
                        record.Unit != null &&
                        factionRules != null &&
                        factionRules.IsNecrons(
                            record.Unit.FactionId) &&
                        record.Unit.HasKeyword(
                            "infantry") &&
                        record.Unit.HasKeyword(
                            "character") &&
                        !record.Unit.EternalRevenantUsed &&
                        !record.Model.IsAlive &&
                        GetCommandPoints(
                            record.Unit.FactionId
                        ) >= 1
                )
                .GroupBy(
                    record => record.Model
                )
                .Select(group => group.First())
                .ToList();

        if (eligible.Count == 0)
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (DestroyedModelRecord record
            in eligible)
        {
            DestroyedModelRecord captured = record;

            options.Add(
                new RuleChoiceOption(
                    "Eternal Revenant: " +
                    captured.Unit.DisplayName +
                    " (1 CP)",
                    () =>
                    {
                        CloseRuleChoice();

                        if (!SpendFactionStratagemCP(
                                captured.Unit,
                                1,
                                "Protocol of the Eternal Revenant"))
                        {
                            ContinueEndPhaseFlow();
                            return;
                        }

                        Vector3 position;

                        if (!TryFindSafeRevivePosition(
                                captured.Model,
                                captured.Position,
                                captured.Unit.FactionId,
                                out position))
                        {
                            status =
                                "Eternal Revenant could not find a legal unengaged setup position.";
                            ContinueEndPhaseFlow();
                            return;
                        }

                        captured.Unit.DetachFromBodyguard();
                        captured.Unit.EternalRevenantUsed = true;

                        captured.Model.Revive(
                            Mathf.CeilToInt(
                                captured.Model.MaxWounds /
                                2f
                            ),
                            position
                        );

                        captured.Unit.RefreshVisuals();
                        RefreshObjectiveDisplays();

                        status =
                            "PROTOCOL OF THE ETERNAL REVENANT: " +
                            captured.Unit.DisplayName +
                            " returned with half wounds.";

                        ContinueEndPhaseFlow();
                    }
                )
            );
        }

        options.Add(
            new RuleChoiceOption(
                "Skip",
                () =>
                {
                    CloseRuleChoice();
                    ContinueEndPhaseFlow();
                }
            )
        );

        OpenRuleChoice(
            "PROTOCOL OF THE ETERNAL REVENANT",
            "An eligible Necron Infantry Character was destroyed this phase. It can return at the end of the phase.",
            options
        );
    }

    private void OfferResurrectionOrb()
    {
        if (resurrectionOrbUsedThisTurn)
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<SquadController> eligible =
            squads
                .Where(
                    unit =>
                        unit != null &&
                        !unit.IsAttachedLeader &&
                        unit.IsAlive &&
                        unit.IsOnBattlefield &&
                        unit.HasAnyLostWoundsOrModels() &&
                        FactionRuleSystem.UnitOrLeaderHasRule(
                            unit,
                            "Resurrection Orb") &&
                        !unit.ResurrectionOrbUsed &&
                        (unit.AttachedLeader == null ||
                         !unit.AttachedLeader.ResurrectionOrbUsed)
                )
                .ToList();

        if (eligible.Count == 0)
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (SquadController unit
            in eligible)
        {
            SquadController captured = unit;

            options.Add(
                new RuleChoiceOption(
                    "Resurrection Orb: " +
                    captured.DisplayName,
                    () =>
                    {
                        CloseRuleChoice();

                        if (!IsXcomMode)
                        {
                            resurrectionOrbUsedThisTurn = true;

                            if (captured.AttachedLeader != null &&
                                FactionRuleSystem.UnitOrLeaderHasRule(
                                    captured.AttachedLeader,
                                    "Resurrection Orb"))
                            {
                                captured.AttachedLeader.ResurrectionOrbUsed = true;
                            }
                            else
                            {
                                captured.ResurrectionOrbUsed = true;
                            }

                            SelectSquadForAction(
                                captured
                            );

                            manualRestoreEditMode = true;
                            manualWoundEditMode = false;
                            manualRestoreDeadIndex = 0;

                            QueueTraditionalRuleAlert(
                                "RESURRECTION ORB",
                                captured.DisplayName +
                                ": roll the D6 yourself and resolve Reanimation manually. Use WOUND EDIT for healing and RESTORE EDIT for returned models. Warboard will not count the D6 result for you.",
                                1
                            );

                            return;
                        }

                        int roll =
                            DiceRoller.RollD6(
                                "Resurrection Orb: " +
                                captured.DisplayName
                            );

                        int restored =
                            ReanimateUnit(
                                captured,
                                roll
                            );

                        resurrectionOrbUsedThisTurn = true;

                        if (captured.AttachedLeader != null &&
                            FactionRuleSystem.UnitOrLeaderHasRule(
                                captured.AttachedLeader,
                                "Resurrection Orb"))
                        {
                            captured.AttachedLeader.ResurrectionOrbUsed = true;
                        }
                        else
                        {
                            captured.ResurrectionOrbUsed = true;
                        }

                        status =
                            "RESURRECTION ORB: D6=" +
                            roll +
                            ", restored " +
                            restored +
                            " wound(s).";

                        ContinueEndPhaseFlow();
                    }
                )
            );
        }

        options.Add(
            new RuleChoiceOption(
                "Skip",
                () =>
                {
                    CloseRuleChoice();
                    ContinueEndPhaseFlow();
                }
            )
        );

        OpenRuleChoice(
            "RESURRECTION ORB",
            "At the end of the phase, one eligible unit can activate Reanimation Protocols using D6 instead of D3.",
            options
        );
    }

    private int WindriderExtractionLimit()
    {
        if (battlePoints <= 1000)
            return 1;

        if (battlePoints <= 2000)
            return 2;

        return 3;
    }

    private bool IsWindriderExtractionUnit(
        SquadController unit,
        string faction)
    {
        return
            unit != null &&
            !unit.IsAttachedLeader &&
            unit.FactionId == faction &&
            unit.IsAlive &&
            unit.IsOnBattlefield &&
            !IsEngaged(unit) &&
            unit.HasKeyword("asuryani") &&
            (unit.HasKeyword("mounted") ||
             unit.HasKeyword("vyper") ||
             unit.DisplayName.IndexOf(
                 "Vyper",
                 System.StringComparison.OrdinalIgnoreCase
              ) >= 0);
    }

    private void OfferWindriderHostExtraction()
    {
        if (aeldariRules == null)
        {
            ContinueEndPhaseFlow();
            return;
        }

        string windriderFaction =
            factions.FirstOrDefault(
                faction =>
                    faction != activeFaction &&
                    aeldariRules.IsAeldariFaction(
                        faction
                    ) &&
                    aeldariRules.DetachmentIs(
                        faction,
                        AeldariDetachment.WindriderHost
                    )
            );

        if (string.IsNullOrWhiteSpace(
                windriderFaction))
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<SquadController> eligible =
            squads
                .Where(
                    unit =>
                        IsWindriderExtractionUnit(
                            unit,
                            windriderFaction
                        )
                )
                .ToList();

        if (eligible.Count == 0)
        {
            ContinueEndPhaseFlow();
            return;
        }

        ContinueWindriderHostExtraction(
            windriderFaction,
            eligible,
            WindriderExtractionLimit()
        );
    }

    private void ContinueWindriderHostExtraction(
        string faction,
        List<SquadController> eligible,
        int remaining)
    {
        if (remaining <= 0 ||
            eligible == null ||
            eligible.Count == 0)
        {
            status =
                "RIDE THE WIND extraction complete.";

            ContinueEndPhaseFlow();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (SquadController unit
            in eligible.ToList())
        {
            SquadController captured =
                unit;

            options.Add(
                new RuleChoiceOption(
                    "Extract " +
                    captured.DisplayName,
                    () =>
                    {
                        CloseRuleChoice();

                        captured.SendToReserves(
                            true
                        );

                        if (captured.AttachedLeader != null)
                        {
                            captured.AttachedLeader
                                .SendToReserves(
                                    true
                                );
                        }

                        AppendBattleLog(
                            "AELDARI",
                            "Ride the Wind",
                            captured.DisplayName +
                            " was removed at the end of the opponent's turn and placed into Strategic Reserves."
                        );

                        eligible.Remove(
                            captured
                        );

                        ContinueWindriderHostExtraction(
                            faction,
                            eligible,
                            remaining - 1
                        );
                    }
                )
            );
        }

        options.Add(
            new RuleChoiceOption(
                "Done  -  extract no more units",
                () =>
                {
                    CloseRuleChoice();
                    ContinueEndPhaseFlow();
                }
            )
        );

        OpenRuleChoice(
            "WINDRIDER HOST  -  RIDE THE WIND",
            DisplayFactionName(
                faction
            ) +
            " may place up to " +
            remaining +
            " more eligible Asuryani Mounted/Vyper unit(s) into Strategic Reserves.",
            options.ToArray()
        );
    }

    private void OfferVeilOfDarkness()
    {
        string opponent =
            factions.FirstOrDefault(
                faction =>
                    faction != activeFaction &&
                    factionRules != null &&
                    factionRules.IsNecrons(
                        faction
                    )
            );

        if (string.IsNullOrWhiteSpace(
                opponent))
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<SquadController> eligible =
            squads
                .Where(
                    unit =>
                        unit != null &&
                        !unit.IsAttachedLeader &&
                        unit.FactionId == opponent &&
                        unit.IsAlive &&
                        unit.IsOnBattlefield &&
                        !IsEngaged(unit) &&
                        FactionRuleSystem.UnitOrLeaderHasRule(
                            unit,
                            "Veil of Darkness") &&
                        !unit.VeilOfDarknessUsed
                )
                .ToList();

        if (eligible.Count == 0)
        {
            ContinueEndPhaseFlow();
            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (SquadController unit
            in eligible)
        {
            SquadController captured = unit;

            options.Add(
                new RuleChoiceOption(
                    "Veil of Darkness: " +
                    captured.DisplayName,
                    () =>
                    {
                        CloseRuleChoice();

                        captured.VeilOfDarknessUsed = true;
                        captured.TemporaryDeepStrike = true;
                        captured.MustIngressFromVeil = true;
                        captured.SendToReserves(true);

                        if (captured.AttachedLeader != null)
                        {
                            captured.AttachedLeader.VeilOfDarknessUsed = true;
                            captured.AttachedLeader.TemporaryDeepStrike = true;
                            captured.AttachedLeader.MustIngressFromVeil = true;
                            captured.AttachedLeader.SendToReserves(true);
                        }

                        status =
                            "VEIL OF DARKNESS: " +
                            captured.DisplayName +
                            " entered Strategic Reserves and must ingress next Movement phase.";

                        ContinueEndPhaseFlow();
                    }
                )
            );
        }

        options.Add(
            new RuleChoiceOption(
                "Skip",
                () =>
                {
                    CloseRuleChoice();
                    ContinueEndPhaseFlow();
                }
            )
        );

        OpenRuleChoice(
            "VEIL OF DARKNESS",
            "End of the opponent's turn: an eligible unengaged bearer unit can enter Strategic Reserves.",
            options
        );
    }

    private bool TryFindSafeRevivePosition(
        ModelToken model,
        Vector3 origin,
        string faction,
        out Vector3 result)
    {
        result = origin;

        float[] radii =
        {
            0f,
            0.9f,
            1.4f,
            2.0f,
            2.8f
        };

        foreach (float radius
            in radii)
        {
            for (int angle = 0;
                 angle < 360;
                 angle += 30)
            {
                float radians =
                    angle *
                    Mathf.Deg2Rad;

                Vector3 candidate =
                    origin +
                    new Vector3(
                        Mathf.Cos(radians) *
                            radius,
                        0f,
                        Mathf.Sin(radians) *
                            radius
                    );

                candidate.y =
                    model.transform.position.y;

                if (!InsideBoard(candidate))
                    continue;

                bool enemyTooClose =
                    squads.Any(
                        enemy =>
                            enemy != null &&
                            enemy.IsAlive &&
                            enemy.IsOnBattlefield &&
                            enemy.FactionId !=
                                faction &&
                            JoinedModels(enemy).Any(
                                enemyModel =>
                                    HorizontalDistance(
                                        candidate,
                                        enemyModel.transform.position
                                    ) <=
                                        EngagementRange +
                                        0.05f
                            )
                    );

                if (enemyTooClose)
                    continue;

                bool occupied =
                    squads.Any(
                        squad =>
                            squad != null &&
                            squad.IsOnBattlefield &&
                            JoinedModels(squad).Any(
                                other =>
                                    other != model &&
                                    HorizontalDistance(
                                        candidate,
                                        other.transform.position
                                    ) <
                                        MinimumModelSeparation(
                                            model,
                                            other
                                        )
                            )
                    );

                if (occupied)
                    continue;

                result = candidate;
                return true;
            }
        }

        return false;
    }

    private void NextPhase()
    {
        // WARBOARD_V46_STANDARD_PHASE_GATE
        string standardFactionPhaseReason;

        if (!WarboardFactionExtensionHub
                .CanAdvancePhase(
                    this,
                    out standardFactionPhaseReason))
        {
            status = standardFactionPhaseReason;
            return;
        }

        string core11PhaseReason;
        if (!Core11CanAdvancePhase(out core11PhaseReason))
        {
            status = core11PhaseReason;
            return;
        }


        // v40 / 11e 12: Pile In, Fight and Consolidate are distinct
        // phase-wide steps and cannot be bypassed with NEXT PHASE.
        if (phase == Phase.Fight)
        {
            string fight11Reason;
            if (!Fight11CanLeaveFightPhase(out fight11Reason))
            {
                status = fight11Reason;
                return;
            }
        }

        if (traditionalAttackPending)
        {
            status =
                "Finish the declared Traditional attack and click ATTACK RESOLVED before changing phase.";
            return;
        }

        if (TraditionalStateResolutionPending())
        {
            status =
                "Finish the current Traditional tabletop state prompt before changing phase.";
            return;
        }

        if (interactiveAttack != null)
        {
            status =
                "Finish the current dice sequence before changing phase.";
            return;
        }

        if (fightActivationStage !=
            FightActivationStage.None)
        {
            status =
                "Finish the current pile-in / melee / consolidation activation before changing phase.";
            return;
        }

        if (showRuleChoiceWindow ||
            specialMoveSquad != null ||
            specialShootUnit != null ||
            endPhaseFlowRunning)
        {
            status =
                "Resolve the current rules/reaction flow first.";
            return;
        }

        if (showStratagemReaction)
        {
            status =
                "Resolve the stratagem reaction window first.";
            return;
        }

        if (showStratagemMenu)
            showStratagemMenu = false;

        if (phase == Phase.Fight &&
            fightSequenceActive &&
            AnyEligibleFightUnits())
        {
            status =
                "Cannot leave the Fight phase: eligible units still have to fight. " +
                FightPriorityText();
            return;
        }

        if (phase == Phase.Move)
        {
            // 11e 09.02.01: every unit must be selected in the Move Units step. Untouched units resolve as Remain Stationary without move-start/end triggers.
            ResolveImplicitRemainStationarySelections();

            SquadController veilUnit =
                squads.FirstOrDefault(
                    squad =>
                        squad != null &&
                        squad.FactionId ==
                            activeFaction &&
                        squad.IsInReserves &&
                        squad.MustIngressFromVeil
                );

            if (veilUnit != null)
            {
                status =
                    "Cannot leave Move phase: " +
                    veilUnit.DisplayName +
                    " used Veil of Darkness and must make its ingress move now.";
                return;
            }

            SquadController badFallback =
                squads.FirstOrDefault(
                    squad =>
                        squad.IsAlive &&
                        squad.IsOnBattlefield &&
                        squad.FactionId ==
                            activeFaction &&
                        squad.HasFallenBack &&
                        IsEngaged(squad)
                );

            if (badFallback != null)
            {
                status =
                    "Cannot leave Move phase: " +
                    badFallback.DisplayName +
                    " started a Fall Back but is still in engagement range.";
                return;
            }

            if (!ActiveFactionIsCoherent())
            {
                SquadController bad =
                    FirstIncoherentSquad();

                status =
                    "Cannot leave Move phase: " +
                    bad.DisplayName +
                    " is out of coherency (" +
                    bad.IncoherentModelCount() +
                    " model(s) invalid).";
                return;
            }
        }

        BuildEndPhaseFlow();
        ContinueEndPhaseFlow();
    }

    private void CompletePhaseTransition()
    {
        // 11e 14.02.01: objective control is determined before other end-of-phase rules.
        ResolveCoreObjectiveControlTiming();


        string factionPhaseSummary = "";

        ApplyAeldariEndOfPhaseObjectiveRules();

        foreach (ObjectiveController objective
            in objectives)
        {
            if (objective != null)
            {
                objective.ResolveSecuredControlAtEndOfPhase(
                    squads
                );
            }
        }

        foreach (SquadController squad
            in squads)
        {
            if (squad != null)
                squad.ClearFactionPhaseEffects();
        }

        ClearSelection();
        ClearArmedCommandReroll();
        showStratagemMenu = false;

        Phase leavingPhase =
            phase;

        NotifyPhaseEnded(leavingPhase);

        if (phase == Phase.Command &&
            missionSystem != null)
        {
            factionPhaseSummary =
                missionSystem
                    .ResolveCommandScoring(
                        activeFaction,
                        round
                    );
        }

        if (phase == Phase.Command)
            phase = Phase.Move;
        else if (phase == Phase.Move)
            phase = Phase.Shoot;
        else if (phase == Phase.Shoot)
            phase = Phase.Charge;
        else if (phase == Phase.Charge)
            phase = Phase.Fight;
        else if (phase == Phase.Fight)
            phase = Phase.End;
        else
        {
            EndTurn();
            return;
        }

        if (leavingPhase == Phase.Fight)
        {
            heraldOfYnneadTarget = null;
            heraldOfYnneadFaction = "";
        }

        if (phase == Phase.Move)
        {
            foreach (SquadController unit
                in squads)
            {
                if (unit != null &&
                    unit.FactionId ==
                        activeFaction)
                {
                    unit.SpiritMarkTarget = null;
                }
            }
        }

        CaptureObjectiveControlAtPhaseStart();
        ClearPhaseDestructionRecords();
        stratagemsUsedThisPhase.Clear();

        RaisePhaseStarted();

        status =
            ActiveFactionDisplayName() +
            " " +
            phase.ToString() +
            " phase.";

        if (!string.IsNullOrWhiteSpace(
                factionPhaseSummary))
        {
            status +=
                " | " +
                factionPhaseSummary;
        }

        if (phase == Phase.Fight)
        {
            BeginFightPhaseFlow();
        }
    }

    public void ResolveDeadlyDemise(
        ModelToken destroyedModel)
    {
        if (destroyedModel == null ||
            destroyedModel.Squad == null)
        {
            return;
        }

        string expression =
            UniversalRuleRegistry
                .GetDeadlyDemiseExpression(
                    destroyedModel.Squad
                );

        if (string.IsNullOrWhiteSpace(
            expression))
        {
            return;
        }

        if (!IsXcomMode)
        {
            QueueTraditionalRuleAlert(
                "DEADLY DEMISE",
                destroyedModel.Squad.DisplayName +
                " has Deadly Demise " +
                expression +
                ". Resolve the trigger and resulting mortal wounds manually, then apply them with WOUND EDIT / REMOVE.",
                1
            );

            return;
        }

        int trigger =
            DiceRoller.RollD6(
                "Deadly Demise: " +
                destroyedModel.Squad.DisplayName
            );

        if (trigger != 6)
            return;

        Vector3 origin =
            destroyedModel.transform.position;

        List<SquadController> affected =
            squads
                .Where(
                    squad =>
                        squad != null &&
                        squad.IsAlive &&
                        squad.IsOnBattlefield &&
                        !squad.IsAttachedLeader &&
                        squad !=
                            destroyedModel.Squad
                )
                .Where(
                    squad =>
                        JoinedModels(squad)
                            .Any(
                                model =>
                                    HorizontalDistance(
                                        origin,
                                        model.transform.position
                                    ) <= 6f
                            )
                )
                .ToList();

        foreach (SquadController squad
            in affected)
        {
            int mortal =
                RollSimpleExpression(
                    expression,
                    "Deadly Demise damage: " +
                    squad.DisplayName
                );

            ApplyMortalWounds(
                squad,
                mortal,
                "Deadly Demise"
            );
        }

        status =
            destroyedModel.Squad.DisplayName +
            " triggered Deadly Demise " +
            expression +
            ".";
    }

    private int RollSimpleExpression(
        string expression,
        string label)
    {
        if (string.IsNullOrWhiteSpace(
            expression))
        {
            return 0;
        }

        string value =
            expression
                .Trim()
                .ToUpperInvariant()
                .Replace(" ", "");

        int flat;

        if (int.TryParse(
            value,
            out flat))
        {
            return Mathf.Max(
                0,
                flat
            );
        }

        int dIndex =
            value.IndexOf('D');

        if (dIndex < 0)
            return 0;

        int count = 1;

        if (dIndex > 0)
        {
            int parsedCount;

            if (int.TryParse(
                value.Substring(
                    0,
                    dIndex
                ),
                out parsedCount))
            {
                count =
                    Mathf.Max(
                        1,
                        parsedCount
                    );
            }
        }

        int modifierIndex = -1;

        for (int i = dIndex + 1;
             i < value.Length;
             i++)
        {
            if (value[i] == '+' ||
                value[i] == '-')
            {
                modifierIndex = i;
                break;
            }
        }

        string sidesText =
            modifierIndex >= 0
            ? value.Substring(
                dIndex + 1,
                modifierIndex - dIndex - 1
              )
            : value.Substring(
                dIndex + 1
              );

        int sides;

        if (!int.TryParse(
            sidesText,
            out sides))
        {
            return 0;
        }

        int result =
            DiceRoller.RollDice(
                count,
                sides,
                label
            ).Total;

        if (modifierIndex >= 0)
        {
            int modifier;

            if (int.TryParse(
                value.Substring(
                    modifierIndex
                ),
                out modifier))
            {
                result += modifier;
            }
        }

        return Mathf.Max(
            0,
            result
        );
    }

    private void EndTurn()
    {
        // 11e: objective control is determined first at end of turn, before other rules and mission resolution.
        ResolveCoreObjectiveControlTiming();


        NotifyTurnEnded();

        string missionScore = "";
        string secondaryScore = "";

        if (missionSystem != null)
        {
            missionScore =
                missionSystem
                    .ResolveEndTurnScoring(
                        activeFaction,
                        round
                    );

            secondaryScore =
                missionSystem
                    .ResolveAutomaticSecondaryScoring(
                        activeFaction,
                        round
                    );

            missionSystem.EndTurnSnapshot();
        }

        foreach (SquadController squad
            in squads)
        {
            if (squad != null &&
                squad.FactionId ==
                    activeFaction)
            {
                squad.ClearFactionTurnEffects();
            }
        }

        RefreshObjectiveDisplays();

        turnsCompletedThisRound++;

        if (turnsCompletedThisRound >=
            factions.Count)
        {
            NotifyBattleRoundEnded();

            turnsCompletedThisRound = 0;

            if (round >= 5)
            {
                FinishBattle(
                    missionScore
                );

                return;
            }

            if (round == 3)
            {
                foreach (SquadController reserve
                    in squads)
                {
                    if (reserve != null &&
                        reserve.IsAlive &&
                        reserve.IsInReserves &&
                        !reserve.IsRepositionedReserve)
                    {
                        reserve
                            .DestroyReserveWithoutTriggers();
                    }
                }
            }

            round++;

            NotifyBattleRoundStarted();

            activeFactionIndex =
                firstTurnFactionIndex;

            StartFactionBattleRoundRules();
        }
        else
        {
            activeFactionIndex =
                (activeFactionIndex + 1) %
                factions.Count;
        }

        activeFaction =
            factions[
                activeFactionIndex
            ];

        BeginActiveTurn(
            false
        );

        if (!string.IsNullOrWhiteSpace(
                missionScore))
        {
            status =
                missionScore +
                " | " +
                status;
        }

        if (!string.IsNullOrWhiteSpace(
                secondaryScore))
        {
            status =
                secondaryScore +
                " | " +
                status;
        }
    }

    private void FinishBattle(
        string finalTurnScore)
    {
        List<string> summaries =
            new List<string>();

        if (!string.IsNullOrWhiteSpace(
                finalTurnScore))
        {
            summaries.Add(
                finalTurnScore
            );
        }

        if (missionSystem != null)
        {
            foreach (string faction
                in factions)
            {
                string endScore =
                    missionSystem
                        .ResolveEndBattleScoring(
                            faction
                        );

                if (!string.IsNullOrWhiteSpace(
                    endScore))
                {
                    summaries.Add(
                        DisplayFactionName(
                            faction
                        ) +
                        ": " +
                        endScore
                    );
                }
            }
        }

        battleOver = true;
        deploymentMode = false;
        showMissionPanel = false;

        string winner = "";

        if (factions.Count >= 2)
        {
            int p1 =
                score.ContainsKey(
                    factions[0])
                ? score[factions[0]]
                : 0;

            int p2 =
                score.ContainsKey(
                    factions[1])
                ? score[factions[1]]
                : 0;

            if (p1 == p2)
            {
                winner =
                    "DRAW  -  " +
                    p1 +
                    " VP each";
            }
            else
            {
                string winningFaction =
                    p1 > p2
                    ? factions[0]
                    : factions[1];

                winner =
                    DisplayFactionName(
                        winningFaction
                    ) +
                    " wins " +
                    Mathf.Max(p1, p2) +
                    " - " +
                    Mathf.Min(p1, p2) +
                    " VP";
            }
        }

        battleSummary =
            winner +
            "\n\n" +
            string.Join(
                "\n",
                factions.Select(
                    faction =>
                        DisplayFactionName(
                            faction
                        ) +
                        "  -  Primary " +
                        TotalScoreType(
                            faction,
                            true
                        ) +
                        " / Secondary " +
                        TotalScoreType(
                            faction,
                            false
                        ) +
                        " / Total " +
                        (score.ContainsKey(
                            faction)
                            ? score[faction]
                            : 0)
                ).ToArray()
            ) +
            (summaries.Count > 0
                ? "\n\n" +
                  string.Join(
                      "\n",
                      summaries.ToArray()
                  )
                : "");

        status =
            winner;
    }

    private void HandleCamera()
    {
        if (gameCamera == null)
            return;

        float speed =
            12f *
            Time.deltaTime;

        Vector3 move =
            Vector3.zero;

        if (Input.GetKey(KeyCode.W))
            move += Vector3.forward;

        if (Input.GetKey(KeyCode.S))
            move += Vector3.back;

        if (Input.GetKey(KeyCode.A))
            move += Vector3.left;

        if (Input.GetKey(KeyCode.D))
            move += Vector3.right;

        gameCamera.transform.position +=
            move.normalized *
            speed;

        float scroll =
            Input.mouseScrollDelta.y;

        if (Mathf.Abs(scroll) > 0.01f)
        {
            Vector3 p =
                gameCamera.transform.position;

            p.y =
                Mathf.Clamp(
                    p.y -
                    scroll * 2f,
                    8f,
                    Mathf.Max(
                        30f,
                        BoardDepth *
                            1.10f
                    )
                );

            gameCamera.transform.position = p;
        }
    }

    private string BattleShockText()
    {
        int shocked =
            squads.Count(
                squad =>
                    squad != null &&
                    squad.IsAlive &&
                    squad.IsOnBattlefield &&
                    !squad.IsAttachedLeader &&
                    squad.FactionId ==
                        activeFaction &&
                    squad
                        .JoinedActionController()
                        .IsBattleShocked
            );

        return shocked == 0
            ? "Battle-shock: none"
            : "Battle-shock: " +
              shocked +
              " unit(s)";
    }

