    private List<string> DeadBoxEntries(
        string faction)
    {
        List<string> entries =
            new List<string>();

        foreach (SquadController squad
            in squads)
        {
            if (squad == null ||
                squad.FactionId !=
                    faction)
            {
                continue;
            }

            int casualties =
                Mathf.Max(
                    0,
                    squad.StartingModels -
                    squad.LivingModels
                );

            if (casualties <= 0)
                continue;

            entries.Add(
                squad.DisplayName +
                "  -  " +
                casualties +
                " dead" +
                (!squad.IsAlive
                    ? " [DESTROYED]"
                    : "")
            );
        }

        return entries;
    }

    private string ShortDiceLabel(
        string label)
    {
        if (string.IsNullOrWhiteSpace(
            label))
        {
            return "Roll";
        }

        if (label.Length <= 12)
            return label;

        return label.Substring(
            0,
            11
        ) + "...";
    }

    private ForceDisposition NextDisposition(
        ForceDisposition value)
    {
        ForceDisposition[] all =
            MissionRegistry.AllDispositions;

        int index =
            System.Array.IndexOf(
                all,
                value
            );

        index =
            (index + 1) %
            all.Length;

        return all[index];
    }

    private static float HorizontalDistance(
        Vector3 a,
        Vector3 b)
    {
        return Vector2.Distance(
            new Vector2(a.x, a.z),
            new Vector2(b.x, b.z)
        );
    }

    private static float HorizontalMagnitude(Vector3 vector)
    {
        return new Vector2(vector.x, vector.z).magnitude;
    }

    public static void SetObjectColor(GameObject go, Color color)
    {
        Renderer renderer =
            go.GetComponent<Renderer>();

        if (renderer == null)
            return;

        Shader shader =
            Shader.Find("Standard");

        if (shader == null)
            shader =
                Shader.Find(
                    "Universal Render Pipeline/Lit"
                );

        if (shader == null)
            shader =
                Shader.Find(
                    "Sprites/Default"
                );

        if (shader == null)
            return;

        Material material =
            new Material(shader);

        material.color = color;
        renderer.material = material;
    }

}
